window.CODE_INDEX = {"classes":{"CommunityContentState":{"appearsIn":[["home","h-classes","Logic \u00b7 class diagram"]],"code":"data class CommunityContentState(\n    val cards: List<Card> = emptyList(),\n    val wikiSite: WikiSite = WikiSite.forLanguageCode(Prefs.homeLanguageCode),\n    val isInitialLoading: Boolean = false,\n    val isLoadingMore: Boolean = false,\n    val error: Throwable? = null,\n    val canLoadMore: Boolean = true,\n    val emptyState: FeedEmptyState? = null\n)","file":"app/src/main/java/org/wikipedia/feed/HomeViewModel.kt","kind":"data class","line":204,"members":{"canLoadMore":[210,210],"cards":[205,205],"emptyState":[211,211],"error":[209,209],"isInitialLoading":[207,207],"isLoadingMore":[208,208],"wikiSite":[206,206]},"supers":[]},"CommunityContentTab":{"appearsIn":[["home","h-widgets","Screen \u00b7 composition"],["home","h-sequence","Load more of the Community feed \u00b7 sequence"]],"code":"@Composable\nfun CommunityContentTab(\n    modifier: Modifier = Modifier,\n    wikiSite: WikiSite,\n    state: CommunityContentState,\n    overflowMenuState: PageOverflowMenuViewModel.PageOverflowMenuState? = null,\n    savedInReadingListTitles: Set<String> = emptySet(),\n    onAction: (HomeAction) -> Unit = {}\n) {\n    when {\n        state.isInitialLoading -> {\n            LoadingIndicator(modifier = modifier.fillMaxHeight())\n        }\n        state.emptyState == FeedEmptyState.ALL_MODULES_HIDDEN || state.emptyState == FeedEmptyState.NO_DATA -> {\n            val context = LocalContext.current\n            val card = EmptyCommunityCard()\n            onAction(HomeAction.CardImpression(card, 0))\n            FeedEmptyStateView(\n                modifier = Modifier\n                    .fillMaxSize()\n                    .background(WikipediaTheme.colors.paperColor)\n                    .padding(16.dp)\n                    .verticalScroll(rememberScrollState()),\n                title = context.getString(wikiSite.languageCode, R.string.home_feed_screen_empty_state_label),\n                description = context.getString(wikiSite.languageCode, R.string.home_feed_community_screen_all_modules_disabled_description),\n                buttonText = context.getString(wikiSite.languageCode, R.string.home_feed_screen_all_modules_disabled_btn_label),\n                onCallToActionClick = { onAction(HomeAction.ManageModulesClick) }\n            )\n        }\n\n        state.error != null && state.cards.isEmpty() -> {\n            ErrorState(state.error, onRetry = { onAction(HomeAction.LoadMoreCommunityContent) })\n        }\n        else -> {\n            val layoutDirection = if (L10nUtil.isLangRTL(wikiSite.languageCode)) LayoutDirection.Rtl else LayoutDirection.Ltr\n            CompositionLocalProvider(LocalLayoutDirection provides layoutDirection) {\n                LazyColumn(\n                    modifier = modifier.fillMaxSize(),\n                    contentPadding = PaddingValues(top = 16.dp, bottom = 16.dp)\n                ) {\n                    item {\n                        CommunityDisclaimer(\n                            modifier = Modifier\n                                .padding(horizontal = 16.dp)\n                                .fillMaxWidth(),\n                            wikiSite = wikiSite\n                        )\n                        Spacer(modifier = Modifier.height(16.dp))\n                    }\n                    var lastCardWasDayHeader = false\n                    state.cards.forEachIndexed { cardIndex, card ->\n                        when (card) {\n                            is DayHeaderCard -> {\n                                item(key = \"day-header-${card.age}\") {\n                                    DayHeader(LocalDate.now().minusDays(card.age.toLong()), isFirst = card.age == 0)\n                                }\n                            }\n                            is FeaturedArticleCard -> {\n                                item(key = \"tfa-${card.age}\") {\n                                    FeaturedArticleModule(\n                                        wikiSite = wikiSite,\n                                        card.page,\n                                        isInReadingList = savedInReadingListTitles.contains(card.page.apiTitle),\n                                        onPageClick = {\n                                            onAction(HomeAction.PageClick(card,\n                                                it.getHistoryEntry(\n                                                    wikiSite,\n                                                    HistoryEntry.SOURCE_FEED_FEATURED\n                                                )\n                                            ))\n                                        },\n                                        onHideCardClick = { onAction(HomeAction.HideCommunityCard(card)) },\n                                        onHideModuleClick = {\n                                            onAction(HomeAction.HideModule(card.moduleKey()))\n                                        },\n                                        onShareClick = {\n                                            onAction(HomeAction.PageShareClick(card,\n                                                it.getHistoryEntry(\n                                                    wikiSite,\n                                                    HistoryEntry.SOURCE_FEED_FEATURED\n                                                )\n                                            ))\n                                        },\n                                        onBookmarkClick = {\n                                            onAction(HomeAction.PageBookmarkClick(card,\n                                                it.getHistoryEntry(\n                                                    wikiSite,\n                                                    HistoryEntry.SOURCE_FEED_FEATURED\n                                                )\n                                            ))\n                                        },\n                                        onCardImpression = { onAction(HomeAction.CardImpression(card, cardIndex)) }\n                                    )\n                                }\n                            }\n                            is TopReadCard -> {\n                                if (lastCardWasDayHeader) {\n                                    item(key = \"top-read-spacer-${card.age}\") {\n                                        Spacer(modifier = Modifier.height(16.dp))\n                                    }\n                                }\n                                item(key = \"top-read-${card.age}\") {\n                                    TopReadModule(\n                                        wikiSite = wikiSite,\n                                        topRead = card.articles,\n                                        pageOverflowContent = { index ->\n                                            PageOverflowMenu(\n                                                menuKey = \"top-read-${card.age}-$index\",\n                                                overflowMenuState = overflowMenuState,\n                                                onDismiss = { onAction(HomeAction.PageOverflowDismiss) },\n                                                onItemClick = { item, entry -> onAction(HomeAction.PageOverflowItemClick(card, item, entry)) }\n                                            )\n                                        },\n                                        onHideCardClick = { onAction(HomeAction.HideCommunityCard(card)) },\n                                        onHideModuleClick = {\n                                            onAction(HomeAction.HideModule(card.moduleKey()))\n                                        },\n                                        onPageClick = { entry ->\n                                            onAction(HomeAction.PageClick(card,\n                                                entry.getHistoryEntry(\n                                                    wikiSite,\n                                                    HistoryEntry.SOURCE_FEED_MOST_READ\n                                                )\n                                            ))\n                                        },\n                                        onPageOverflowClick = { pageSummary, index ->\n                                            onAction(HomeAction.PageOverflowClick(card, pageSummary, HistoryEntry.SOURCE_FEED_MOST_READ, \"top-read-${card.age}-$index\"))\n                                        },\n                                        onFooterClick = { onAction(HomeAction.CardFooterClick(card)) },\n                                        onCardImpression = { onAction(HomeAction.CardImpression(card, cardIndex)) }\n                                    )\n                                }\n                            }\n                            is NewsCard -> {\n                                item(key = \"news-${card.age}\") {\n                                    NewsModule(\n                                        wikiSite = wikiSite,\n                                        newsItems = card.news,\n                                        onHideCardClick = { onAction(HomeAction.HideCommunityCard(card)) },\n                                        onHideModuleClick = {\n                                            onAction(HomeAction.HideModule(card.moduleKey()))\n                                        },\n                                        onNewsClick = { newsItem ->\n                                            onAction(HomeAction.NewsClick(card, newsItem))\n                                        },\n                                        onCardImpression = { onAction(HomeAction.CardImpression(card, cardIndex)) }\n                                    )\n                                }\n                            }\n                            is OnThisDayCard -> {\n                                if (lastCardWasDayHeader) {\n                                    item(key = \"on-this-day-spacer-${card.age}\") {\n                                        Spacer(modifier = Modifier.height(16.dp))\n                                    }\n                                }\n                                item(key = \"on-this-day-${card.age}\") {\n                                    OnThisDayModule(\n                                        wikiSite = wikiSite,\n                                        events = card.events,\n                                        pageOverflowContent = { eventIndex, itemIndex ->\n                                            PageOverflowMenu(\n                                                menuKey = \"on-this-day-${card.age}-$eventIndex-$itemIndex\",\n                                                overflowMenuState = overflowMenuState,\n                                                onDismiss = { onAction(HomeAction.PageOverflowDismiss) },\n                                                onItemClick = { item, entry -> onAction(HomeAction.PageOverflowItemClick(card, item, entry)) }\n                                            )\n                                        },\n                                        onHideCardClick = { onAction(HomeAction.HideCommunityCard(card)) },\n                                        onHideModuleClick = {\n                                            onAction(HomeAction.HideModule(card.moduleKey()))\n                                        },\n                                        onPageClick = { pageSummary ->\n                                            onAction(HomeAction.PageClick(card, pageSummary.getHistoryEntry(wikiSite, HistoryEntry.SOURCE_FEED_ON_THIS_DAY)))\n                                        },\n                                        onPageOverflowClick = { pageSummary, eventIndex, itemIndex ->\n                                            onAction(HomeAction.PageOverflowClick(card, pageSummary, HistoryEntry.SOURCE_FEED_ON_THIS_DAY, \"on-this-day-${card.age}-$eventIndex-$itemIndex\"))\n                                        },\n                                        onFooterClick = { onAction(HomeAction.CardFooterClick(card)) },\n                                        onCardImpression = { onAction(HomeAction.CardImpression(card, cardIndex)) }\n                                    )\n                                }\n                            }\n                            is FeaturedImageCard -> {\n                                item(key = \"tfi-${card.age}\") {\n                                    FeaturedImageModule(\n                                        wikiSite = wikiSite,\n                                        card = card,\n                                        onHideCardClick = { onAction(HomeAction.HideCommunityCard(card)) },\n                                        onHideModuleClick = {\n                                            onAction(HomeAction.HideModule(card.moduleKey()))\n                                        },\n                                        onClick = { onAction(HomeAction.ImageClick(it)) },\n                                        onDownloadClick = { onAction(HomeAction.ImageDownloadClick(it)) },\n                                        onShareClick = { onAction(HomeAction.ImageShareClick(it)) },\n                                        onCardImpression = { onAction(HomeAction.CardImpression(card, cardIndex)) }\n                                    )\n                                }\n                            }\n                            is DidYouKnowCard -> {\n                                item(key = \"dyk-${card.date}\") {\n                                    DidYouKnowModule(\n                                        wikiSite = wikiSite,\n                                        dyk = card.items,\n                                        onHideCardClick = { onAction(HomeAction.HideCommunityCard(card)) },\n                                        onHideModuleClick = {\n                                            onAction(HomeAction.HideModule(card.moduleKey()))\n                                        },\n                                        onPageClick = {\n                                            onAction(HomeAction.PageClick(card, HistoryEntry(it, HistoryEntry.SOURCE_FEED_DID_YOU_KNOW)))\n                                        },\n                                        onFooterClick = { onAction(HomeAction.CardFooterClick(card)) },\n                                        onCardImpression = { onAction(HomeAction.CardImpression(card, cardIndex)) },\n                                        pageOverflowContent = { index ->\n                                            PageOverflowMenu(\n                                                menuKey = \"dyk-${card.date}-$index\",\n                                                overflowMenuState = overflowMenuState,\n                                                onDismiss = { onAction(HomeAction.PageOverflowDismiss) },\n                                                onItemClick = { item, entry -> onAction(HomeAction.PageOverflowItemClick(card, item, entry)) }\n                                            )\n                                        },\n                                        onPageOverflowClick = { pageSummary, index ->\n                                            onAction(HomeAction.PageOverflowClick(card, pageSummary, HistoryEntry.SOURCE_FEED_DID_YOU_KNOW, \"dyk-${card.date}-$index\"))\n                                        }\n                                    )\n                                }\n                            }\n                            else -> {\n                                // TODO: Today's Featured Picture\n                                // TODO: Media of the day (Commons)\n                            }\n                        }\n                        lastCardWasDayHeader = card is DayHeaderCard\n                    }\n\n                    item(key = \"load-more-community\") {\n                        if (state.isLoadingMore) {\n                            LoadingIndicator()\n                        } else if (state.canLoadMore && state.cards.isNotEmpty()) {\n                            LoadMoreButton(\n                                wikiSite = wikiSite,\n                                isCommunity = true,\n                                onClick = { onAction(HomeAction.LoadMoreCommunityContent) }\n                            )\n                        }\n                    }\n\n                    if (state.error != null && state.cards.isNotEmpty()) {\n                        item(key = \"error-community\") {\n                            ErrorState(state.error, onRetry = { onAction(HomeAction.LoadMoreCommunityContent) })\n                        }\n                    }\n                }\n            }\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/feed/CommunityContentTab.kt","kind":"composable function","line":45,"members":{},"shot":"shots/code/CommunityContentTab.jpg","supers":[]},"DayHeader":{"appearsIn":[["home","h-widgets","Screen \u00b7 composition"]],"code":"@Composable\nfun DayHeader(date: LocalDate, isFirst: Boolean = true) {\n    val dateFormatter = DateTimeFormatter.ofPattern(DateFormat.getBestDateTimePattern(LocalLocale.current.platformLocale, \"MMM dd, yyyy\"))\n    Text(\n        text = if (LocalDate.now().dayOfYear == date.dayOfYear) stringResource(R.string.explore_feed_date_today, date.format(dateFormatter)) else date.format(dateFormatter),\n        color = WikipediaTheme.colors.secondaryColor,\n        fontWeight = FontWeight.Bold,\n        fontSize = 14.sp,\n        modifier = Modifier.padding(start = 16.dp, end = 16.dp, top = if (isFirst) 16.dp else 24.dp)\n    )\n}","file":"app/src/main/java/org/wikipedia/feed/FeedComponents.kt","kind":"composable function","line":82,"members":{},"supers":[]},"ErrorState":{"appearsIn":[["home","h-widgets","Screen \u00b7 composition"]],"code":"@Composable\nfun ErrorState(caught: Throwable, onRetry: () -> Unit) {\n    Column(\n        modifier = Modifier\n            .fillMaxWidth()\n            .padding(32.dp),\n        horizontalAlignment = Alignment.CenterHorizontally\n    ) {\n        WikiErrorView(\n            modifier = Modifier,\n            caught,\n            errorClickEvents = WikiErrorClickEvents(\n                retryClickListener = {\n                    onRetry()\n                }\n            ),\n            retryForGenericError = true\n        )\n    }\n}","file":"app/src/main/java/org/wikipedia/feed/FeedComponents.kt","kind":"composable function","line":162,"members":{},"supers":[]},"FeaturedArticleCard":{"appearsIn":[["home","h-classes","Logic \u00b7 class diagram"]],"code":"open class FeaturedArticleCard(\n    val page: PageSummary,\n    val age: Int, wiki: WikiSite,\n) : WikiSiteCard(wiki) {\n\n    override fun moduleKey(): String {\n        return CommunityModuleType.FEATURED_ARTICLE.name\n    }\n\n    override fun dismissHashCode(): Int {\n        return page.apiTitle.hashCode()\n    }\n}","file":"app/src/main/java/org/wikipedia/feed/model/FeaturedArticleCard.kt","kind":"class","line":7,"members":{"age":[9,9],"dismissHashCode":[16,18],"moduleKey":[12,14],"page":[8,8],"wiki":[9,9]},"supers":["WikiSiteCard(wiki)"]},"FeaturedImageCard":{"appearsIn":[["home","h-classes","Logic \u00b7 class diagram"]],"code":"class FeaturedImageCard(\n    val featuredImage: FeaturedImage,\n    val age: Int,\n    wiki: WikiSite\n) : WikiSiteCard(wiki) {\n\n    override fun moduleKey(): String {\n        return CommunityModuleType.FEATURED_IMAGE.name\n    }\n\n    override fun dismissHashCode(): Int {\n        return featuredImage.title.hashCode()\n    }\n}","file":"app/src/main/java/org/wikipedia/feed/model/FeaturedImageCard.kt","kind":"class","line":7,"members":{"age":[9,9],"dismissHashCode":[17,19],"featuredImage":[8,8],"moduleKey":[13,15],"wiki":[10,10]},"supers":["WikiSiteCard(wiki)"]},"ForYouCardContent":{"appearsIn":[["home","h-widgets","Screen \u00b7 composition"]],"code":"@Composable\nfun ForYouCardContent(\n    wikiSite: WikiSite,\n    title: PageTitle,\n    resolveSavedState: suspend (PageTitle) -> Boolean = { false },\n    variation: CardVariation = CardVariation.VARIATION_IMAGE_WITH_EXTRACT,\n    backgroundColorIndex: Int = 0,\n    module: ForYouModule? = null,\n    card: ForYouCard? = null,\n    footerIcon: Painter? = null,\n    footerText: String? = null,\n    footerContent: @Composable () -> Unit = {},\n    onPageClick: (PageTitle) -> Unit = {},\n    onShareClick: (PageTitle) -> Unit = {},\n    onSaveClick: (PageTitle) -> Unit = {},\n    onHideCardClick: (module: ForYouModule, card: ForYouCard) -> Unit = { _, _ -> },\n    onHideModuleClick: () -> Unit = {},\n    @StringRes customizeMenuText: Int = R.string.explore_feed_customize_interests,\n    onCustomizeClick: () -> Unit = {}\n) {\n    val context = LocalContext.current\n    val scope = rememberCoroutineScope()\n    var overflowMenuExpanded by remember { mutableStateOf(false) }\n    // Resolved on demand when the overflow button is tapped, so we never query the whole feed up front.\n    var isInReadingList by remember { mutableStateOf(false) }\n    val showSpaceForPagerDots = (module?.cards?.size ?: 0) > 1\n\n    Box(\n        modifier = Modifier\n            .fillMaxSize()\n            .clickable { onPageClick(title) }\n    ) {\n        val shouldShowTextOnly = title.thumbUrl.isNullOrEmpty() || variation == CardVariation.VARIATION_TEXT_ONLY\n        if (shouldShowTextOnly) {\n            val color = colorResource(noImageCardBackgroundColors[backgroundColorIndex % noImageCardBackgroundColors.size])\n            Box(\n                modifier = Modifier.fillMaxSize().background(color)\n            )\n        } else {\n            FadeInAsyncImage(\n                model = title.thumbUrl?.let { ImageService.getRequest(context,\n                    url = ImageUrlUtil.getUrlForPreferredSize(it, Constants.PREFERRED_CARD_THUMBNAIL_SIZE)) },\n                placeholder = ColorPainter(Color.Black),\n                error = ColorPainter(Color.DarkGray),\n                contentDescription = null,\n                contentScale = ContentScale.Crop,\n                modifier = Modifier.fillMaxSize()\n            )\n        }\n\n        if (shouldShowTextOnly) {\n            Column(\n                modifier = Modifier\n                    .align(Alignment.BottomStart)\n                    .fillMaxWidth()\n            ) {\n                Column(\n                    modifier = Modifier\n                        .fillMaxWidth()\n                        .padding(16.dp)\n                        .clip(RoundedCornerShape(16.dp))\n                        .background(colorResource(noImageCardForegroundColors[backgroundColorIndex % noImageCardForegroundColors.size]))\n                        .padding(16.dp)\n                ) {\n                    val text = title.extract ?: title.description ?: \"\"\n                    HtmlText(\n                        text = text,\n                        color = colorResource(R.color.gray700),\n                        style = MaterialTheme.typography.titleLarge.copy(\n                            fontFamily = FontFamily.Serif\n                        ),\n                        maxLines = 8\n                    )\n                    HorizontalDivider(\n                        modifier = Modifier.padding(vertical = 16.dp).width(48.dp),\n                        thickness = 1.dp,\n                        color = colorResource(noImageCardBackgroundColors[backgroundColorIndex % noImageCardBackgroundColors.size])\n                    )\n\n                    Row(\n                        modifier = Modifier.fillMaxWidth(),\n                        verticalAlignment = Alignment.CenterVertically\n                    ) {\n                        if (!title.thumbUrl.isNullOrEmpty()) {\n                            AsyncImage(\n                                model = title.thumbUrl,\n                                contentDescription = null,\n                                modifier = Modifier.padding(end = 8.dp).size(56.dp)\n                                    .clip(RoundedCornerShape(8.dp)),\n                                contentScale = ContentScale.Crop\n                            )\n                        }\n                        Column(\n                            modifier = Modifier.weight(1f)\n                        ) {\n                            HtmlText(\n                                text = title.displayText,\n                                color = colorResource(R.color.gray700),\n                                style = MaterialTheme.typography.titleSmall,\n                                maxLines = 1\n                            )\n                            HtmlText(\n                                modifier = Modifier.padding(top = 4.dp),\n                                text = title.description ?: \"\",\n                                color = colorResource(R.color.gray700),\n                                style = MaterialTheme.typography.bodySmall,\n                                maxLines = 2\n                            )\n                        }\n                        Column {\n                            IconButton(\n                                modifier = Modifier.size(48.dp),\n                                onClick = {\n                                    scope.launch {\n                                        isInReadingList = resolveSavedState(title)\n                                        overflowMenuExpanded = true\n                                    }\n                                }\n                            ) {\n                                Icon(\n                                    painter = painterResource(R.drawable.ic_more_vert_white_24dp),\n                                    contentDescription = context.getString(\n                                        wikiSite.languageCode,\n                                        R.string.menu_feed_overflow_label\n                                    ),\n                                    tint = colorResource(R.color.gray700),\n                                    modifier = Modifier.size(24.dp)\n                                )\n                            }\n                            ForYouCardDropdownMenu(\n                                expanded = overflowMenuExpanded,\n                                wikiSite = wikiSite,\n                                isInReadingList = isInReadingList,\n                                onDismiss = { overflowMenuExpanded = false },\n                                onShareClick = {\n                                    onShareClick(title)\n                                },\n                                onSaveClick = {\n                                    onSaveClick(title)\n                                },\n                                onHideCardClick = {\n                                    if (module != null && card != null) {\n                                        onHideCardClick(module, card)\n                                    }\n                                },\n                                onHideModuleClick = onHideModuleClick,\n                                customizeMenuText = customizeMenuText,\n                                onCustomizeClick = onCustomizeClick\n                            )\n                        }\n                    }\n                }\n                Row(\n                    modifier = Modifier.fillMaxWidth().padding(start = 16.dp, end = 16.dp),\n                    verticalAlignment = Alignment.CenterVertically\n                ) {\n                    footerIcon?.let {\n                        Icon(\n                            painter = it,\n                            contentDescription = null,\n                            tint = Color.White,\n                            modifier = Modifier.padding(end = 4.dp).size(16.dp)\n                        )\n                    }\n                    footerText?.let {\n                        HtmlText(\n                            text = it,\n                            color = Color.White,\n                            style = MaterialTheme.typography.labelSmall,\n                            maxLines = 8,\n                            overflow = TextOverflow.Ellipsis\n                        )\n                    }\n                }\n                footerContent()\n                Spacer(modifier = Modifier.height(if (showSpaceForPagerDots) 40.dp else 16.dp))\n            }\n        } else {\n            Column(\n                modifier = Modifier.align(Alignment.BottomStart).fillMaxWidth()\n            ) {\n                Box(\n                    modifier = Modifier.fillMaxWidth().height(120.dp)\n                        .background(\n                        Brush.verticalGradient(\n                            colorStops = arrayOf(\n                                0.0f to Color.Transparent,\n                                0.18f to Color.Black.copy(alpha = 0.05f),\n                                0.38f to Color.Black.copy(alpha = 0.15f),\n                                0.58f to Color.Black.copy(alpha = 0.30f),\n                                0.76f to Color.Black.copy(alpha = 0.50f),\n                                0.90f to Color.Black.copy(alpha = 0.7f),\n                                1.0f to Color.Black.copy(alpha = 0.80f)\n                            )\n                        )\n                    )\n                )\n                Column(\n                    modifier = Modifier.background(color = Color.Black.copy(alpha = 0.80f))\n                        .padding(bottom = if (showSpaceForPagerDots) 40.dp else 16.dp)\n                ) {\n                    Row(\n                        modifier = Modifier.fillMaxWidth()\n                    ) {\n                        HtmlText(\n                            modifier = Modifier.weight(1f).padding(start = 16.dp, top = 8.dp),\n                            text = title.displayText,\n                            color = Color.White,\n                            style = MaterialTheme.typography.titleLarge.copy(\n                                fontFamily = FontFamily.Serif\n                            ),\n                            maxLines = 3\n                        )\n                        IconButton(\n                            modifier = Modifier.size(48.dp),\n                            onClick = {\n                                scope.launch {\n                                    isInReadingList = resolveSavedState(title)\n                                    overflowMenuExpanded = true\n                                }\n                            }\n                        ) {\n                            Icon(\n                                painter = painterResource(R.drawable.ic_more_vert_white_24dp),\n                                contentDescription = context.getString(\n                                    wikiSite.languageCode,\n                                    R.string.menu_feed_overflow_label\n                                ),\n                                tint = Color.White,\n                                modifier = Modifier.size(24.dp)\n                            )\n                        }\n                        ForYouCardDropdownMenu(\n                            expanded = overflowMenuExpanded,\n                            wikiSite = wikiSite,\n                            isInReadingList = isInReadingList,\n                            onDismiss = { overflowMenuExpanded = false },\n                            onShareClick = {\n                                onShareClick(title)\n                            },\n                            onSaveClick = {\n                                onSaveClick(title)\n                            },\n                            onHideCardClick = {\n                                if (module != null && card != null) {\n                                    onHideCardClick(module, card)\n                                }\n                            },\n                            onHideModuleClick = onHideModuleClick,\n                            customizeMenuText = customizeMenuText,\n                            onCustomizeClick = onCustomizeClick\n                        )\n                    }\n                    val text = if (variation == CardVariation.VARIATION_IMAGE_WITH_EXTRACT) (title.extract ?: title.description) else title.description\n                    text?.let {\n                        Spacer(modifier = Modifier.height(2.dp))\n                        HtmlText(\n                            modifier = Modifier.padding(horizontal = 16.dp),\n                            text = it,\n                            color = Color.White,\n                            style = MaterialTheme.typography.bodyMedium,\n                            maxLines = 5,\n                            overflow = TextOverflow.Ellipsis\n                        )\n                    }\n                    Row(\n                        modifier = Modifier.fillMaxWidth().padding(start = 16.dp, end = 16.dp, top = 16.dp),\n                        verticalAlignment = Alignment.CenterVertically\n                    ) {\n                        footerIcon?.let {\n                            Icon(\n                                painter = it,\n                                contentDescription = null,\n                                tint = Color.White,\n                                modifier = Modifier.padding(end = 4.dp).size(16.dp)\n                            )\n                        }\n                        footerText?.let {\n                            HtmlText(\n                                text = it,\n                                color = Color.White,\n                                style = MaterialTheme.typography.labelSmall,\n                                maxLines = 8,\n                                overflow = TextOverflow.Ellipsis\n                            )\n                        }\n                    }\n                    footerContent()\n                }\n            }\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/feed/ForYouCard.kt","kind":"composable function","line":68,"members":{},"supers":[]},"ForYouContentState":{"appearsIn":[["home","h-classes","Logic \u00b7 class diagram"]],"code":"data class ForYouContentState(\n    val modules: List<ForYouModule> = emptyList(),\n    val wikiSite: WikiSite = WikiSite.forLanguageCode(Prefs.homeLanguageCode),\n    val isInitialLoading: Boolean = false,\n    val isLoadingMore: Boolean = false,\n    val error: Throwable? = null,\n    val canLoadMore: Boolean = false,\n    val isInterestModuleHidden: Boolean = false,\n    val emptyState: FeedEmptyState? = null\n)","file":"app/src/main/java/org/wikipedia/feed/HomeViewModel.kt","kind":"data class","line":214,"members":{"canLoadMore":[220,220],"emptyState":[222,222],"error":[219,219],"isInitialLoading":[217,217],"isInterestModuleHidden":[221,221],"isLoadingMore":[218,218],"modules":[215,215],"wikiSite":[216,216]},"supers":[]},"ForYouContentTab":{"appearsIn":[["home","h-widgets","Screen \u00b7 composition"]],"code":"@Composable\nfun ForYouContentTab(\n    state: ForYouContentState,\n    topInset: Int,\n    wikiSite: WikiSite,\n    resolveSavedState: suspend (PageTitle) -> Boolean = { false },\n    onAction: (HomeAction) -> Unit = {}\n) {\n    when {\n        state.isInitialLoading -> {\n            Box(\n                modifier = Modifier\n                    .fillMaxSize()\n                    .background(color = WikipediaTheme.colors.backgroundColor),\n                contentAlignment = Alignment.Center\n            ) {\n                LoadingIndicator(modifier = Modifier.fillMaxHeight())\n            }\n        }\n        state.emptyState == FeedEmptyState.NO_DATA -> {\n            val card = EmptyForYouCard()\n            onAction(HomeAction.CardImpression(card, 0))\n            ForYouFeedMessageView(\n                modifier = Modifier\n                    .fillMaxSize()\n                    .background(WikipediaTheme.colors.paperColor)\n                    .padding(horizontal = 16.dp)\n                    .padding(top = (topInset * 2 + 64).dp)\n                    .verticalScroll(rememberScrollState()),\n                wikiSite = wikiSite,\n                illustrationResId = R.drawable.empty_feed_illustration,\n                titleResId = R.string.home_feed_for_you_screen_empty_title,\n                descriptionResId = R.string.home_feed_for_you_screen_empty_description,\n                headerResId = R.string.home_feed_for_you_screen_empty_ways_to_start,\n                customizeInterestsTextResId = R.string.home_feed_for_you_screen_empty_add_interests,\n                showCustomizeInterests = !state.isInterestModuleHidden,\n                onCustomizeClick = { onAction(HomeAction.CustomizeClick(card)) },\n                navigateToCommunityTab = { onAction(HomeAction.SelectTab(HomeTab.COMMUNITY, card)) }\n            )\n        }\n        state.emptyState == FeedEmptyState.ALL_MODULES_HIDDEN -> {\n            val context = LocalContext.current\n            FeedEmptyStateView(\n                modifier = Modifier\n                    .fillMaxSize()\n                    .background(WikipediaTheme.colors.paperColor)\n                    .padding(horizontal = 16.dp)\n                    .padding(top = (topInset * 2 + 64).dp)\n                    .verticalScroll(rememberScrollState()),\n                title = context.getString(wikiSite.languageCode, R.string.home_feed_screen_empty_state_label),\n                description = context.getString(wikiSite.languageCode, R.string.home_feed_for_you_screen_all_modules_disabled_description),\n                buttonText = context.getString(wikiSite.languageCode, R.string.home_feed_screen_all_modules_disabled_btn_label),\n                onCallToActionClick = { onAction(HomeAction.ManageModulesClick) }\n            )\n        }\n        state.error != null && state.modules.isEmpty() -> {\n            Box(\n                modifier = Modifier\n                    .fillMaxSize()\n                    .background(color = WikipediaTheme.colors.backgroundColor),\n                contentAlignment = Alignment.Center\n            ) {\n                ErrorState(state.error, onRetry = { onAction(HomeAction.LoadMoreForYouContent) })\n            }\n        }\n        else -> {\n            val layoutDirection = if (L10nUtil.isLangRTL(wikiSite.languageCode)) LayoutDirection.Rtl else LayoutDirection.Ltr\n            CompositionLocalProvider(LocalLayoutDirection provides layoutDirection) {\n                val listState = rememberLazyListState()\n                val modules = state.modules\n\n                LaunchedEffect(listState, modules.size) {\n                    snapshotFlow {\n                        Pair(listState.firstVisibleItemIndex, listState.isScrollInProgress)\n                    }.collect { (index, isScrolling) ->\n                        val dummyIndex = modules.size + 1\n                        if (!isScrolling && index >= dummyIndex) {\n                            listState.scrollToItem(0)\n                        }\n                    }\n                }\n\n                BoxWithConstraints(modifier = Modifier.fillMaxSize()) {\n                    val viewportHeight = maxHeight\n\n                    LazyColumn(\n                        state = listState,\n                        flingBehavior = rememberSnapFlingBehavior(lazyListState = listState),\n                        modifier = Modifier\n                            .fillMaxSize()\n                            .background(WikipediaTheme.colors.backgroundColor)\n                    ) {\n                        modules.forEachIndexed { index, module ->\n                            forYouModuleItem(\n                                module = module,\n                                index = index,\n                                topInset = topInset,\n                                viewPortHeight = viewportHeight,\n                                wikiSite = wikiSite,\n                                resolveSavedState = resolveSavedState,\n                                onAction = onAction\n                            )\n                        }\n\n                        item(key = \"load-more-foryou\") {\n                            if (state.isLoadingMore) {\n                                LoadingIndicator()\n                            } else if (state.canLoadMore) {\n                                // In case we want to load more For You items in the future:\n                                // LoadMoreButton(\n                                //     wikiSite = wikiSite,\n                                //     isCommunity = false,\n                                //     onClick = onLoadMore\n                                // )\n                            } else if (state.modules.isNotEmpty()) {\n                                // only when we don't serve new content on the same day\n                                val card = EmptyForYouCard()\n                                ForYouFeedMessageView(\n                                    modifier = Modifier\n                                        .fillMaxWidth()\n                                        .height(viewportHeight)\n                                        .background(colorResource(R.color.green800))\n                                        .padding(16.dp)\n                                        .padding(top = (topInset * 2 + 64).dp)\n                                        .navigationBarsPadding(),\n                                    wikiSite = wikiSite,\n                                    illustrationResId = R.drawable.yir_puzzle_browser,\n                                    titleResId = R.string.home_feed_for_you_screen_end_of_feed_title,\n                                    descriptionResId = R.string.home_feed_for_you_screen_end_of_feed_description,\n                                    headerResId = R.string.home_feed_for_you_screen_end_of_feed_ways_to_keep_learning,\n                                    customizeInterestsTextResId = R.string.home_feed_for_you_screen_end_of_feed_add_interests,\n                                    onCustomizeClick = { onAction(HomeAction.CustomizeClick(card)) },\n                                    navigateToCommunityTab = { onAction(HomeAction.SelectTab(HomeTab.COMMUNITY, card)) }\n                                )\n                            }\n                        }\n\n                        if (state.error != null && state.modules.isNotEmpty()) {\n                            item(key = \"error-foryou\") {\n                                ErrorState(state.error, onRetry = { onAction(HomeAction.LoadMoreForYouContent) })\n                            }\n                        }\n\n                        if (state.error == null && !state.isLoadingMore && !state.canLoadMore && state.modules.isNotEmpty()) {\n                            forYouModuleItem(\n                                module = state.modules.first(),\n                                index = modules.size + 1,\n                                topInset = topInset,\n                                viewPortHeight = viewportHeight,\n                                wikiSite = wikiSite,\n                                resolveSavedState = resolveSavedState,\n                                onAction = onAction,\n                                onCardImpression = { _, _ -> }\n                            )\n                        }\n                    }\n                }\n            }\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/feed/ForYouContentTab.kt","kind":"composable function","line":76,"members":{},"shot":"shots/code/ForYouContentTab.jpg","supers":[]},"ForYouModule":{"appearsIn":[["home","h-classes","Logic \u00b7 class diagram"]],"code":"@Serializable\nsealed class ForYouModule {\n    abstract val age: Int\n    abstract val index: Int\n    abstract val cards: List<ForYouCard>\n\n    abstract fun withCards(cards: List<ForYouCard>): ForYouModule\n    abstract fun moduleKey(): String\n\n    @Serializable\n    data class BasedOnInterest(\n        override val age: Int,\n        override val index: Int,\n        override val cards: List<ForYouCard>\n    ) : ForYouModule() {\n        override fun withCards(cards: List<ForYouCard>): ForYouModule = copy(cards = cards)\n        override fun moduleKey(): String = ForYouModuleType.BASED_ON_INTEREST.name\n    }\n\n    @Serializable\n    data class ContinueReading(\n        override val age: Int,\n        override val index: Int,\n        override val cards: List<ForYouCard>\n    ) : ForYouModule() {\n        override fun withCards(cards: List<ForYouCard>): ForYouModule = copy(cards = cards)\n        override fun moduleKey(): String = ForYouModuleType.CONTINUE_READING.name\n    }\n\n    @Serializable\n    data class BecauseYouRead(\n        override val age: Int,\n        override val index: Int,\n        override val cards: List<ForYouCard>\n    ) : ForYouModule() {\n        override fun withCards(cards: List<ForYouCard>): ForYouModule = copy(cards = cards)\n        override fun moduleKey(): String = ForYouModuleType.BECAUSE_YOU_READ.name\n    }\n\n    @Serializable\n    data class PlacesOfInterest(\n        override val age: Int,\n        override val index: Int,\n        override val cards: List<ForYouCard>,\n        val hasLocationPermission: Boolean,\n        val isLoading: Boolean = false\n    ) : ForYouModule() {\n        override fun withCards(cards: List<ForYouCard>): ForYouModule = copy(cards = cards)\n        override fun moduleKey(): String = ForYouModuleType.PLACES_OF_INTEREST.name\n    }\n\n    @Serializable\n    data class Discover(\n        override val age: Int,\n        override val index: Int,\n        override val cards: List<ForYouCard>,\n        val isEnabled: Boolean,\n        val isLoading: Boolean = false,\n        val updateFrequency: RecommendedReadingListUpdateFrequency = RecommendedReadingListUpdateFrequency.DAILY\n    ) : ForYouModule() {\n        override fun withCards(cards: List<ForYouCard>): ForYouModule = copy(cards = cards)\n        override fun moduleKey(): String = ForYouModuleType.DISCOVER.name\n    }\n\n    @Serializable\n    data class Random(\n        override val age: Int,\n        override val index: Int,\n        override val cards: List<ForYouCard>\n    ) : ForYouModule() {\n        override fun withCards(cards: List<ForYouCard>): ForYouModule = copy(cards = cards)\n        override fun moduleKey(): String = ForYouModuleType.RANDOM.name\n    }\n\n    data class Games(\n        override val age: Int,\n        override val index: Int,\n        override val cards: List<ForYouCard>,\n        val isLoading: Boolean = false\n    ) : ForYouModule() {\n        override fun withCards(cards: List<ForYouCard>): ForYouModule = copy(cards = cards)\n        override fun moduleKey(): String = ForYouModuleType.GAMES.name\n    }\n\n    @Serializable\n    data class ReadAloudLeadSection(\n        override val age: Int,\n        override val index: Int,\n        override val cards: List<ForYouCard>\n    ) : ForYouModule() {\n        override fun withCards(cards: List<ForYouCard>): ForYouModule = copy(cards = cards)\n        override fun moduleKey(): String = ForYouModuleType.READ_ALOUD_LEAD_SECTION.name\n    }\n}","file":"app/src/main/java/org/wikipedia/feed/HomeViewModel.kt","kind":"class","line":103,"members":{"BasedOnInterest":[112,120],"BecauseYouRead":[132,140],"ContinueReading":[122,130],"Discover":[154,165],"Games":[177,185],"PlacesOfInterest":[142,152],"Random":[167,175],"ReadAloudLeadSection":[187,195],"age":[105,105],"cards":[107,107],"index":[106,106],"moduleKey":[110,110],"withCards":[109,109]},"supers":[]},"HomeAction":{"alsoIn":["app/src/main/java/org/wikipedia/widgets/readingchallenge/ReadingChallengeActions.kt"],"appearsIn":[["home","h-classes","Logic \u00b7 class diagram"]],"code":"sealed interface HomeAction {\n    data class SelectTab(val tab: HomeTab, val card: Card?) : HomeAction\n    data class RefreshTab(val tab: HomeTab) : HomeAction\n    data object LoadMoreCommunityContent : HomeAction\n    data object LoadMoreForYouContent : HomeAction\n    data class HideCommunityCard(val card: Card) : HomeAction\n    data class HideForYouCard(val module: ForYouModule, val card: ForYouCard) : HomeAction\n    data class HideModule(val moduleKey: String) : HomeAction\n    data class PageClick(val card: Card, val historyEntry: HistoryEntry) : HomeAction\n    data class PageBookmarkClick(val card: Card, val historyEntry: HistoryEntry) : HomeAction\n    data class PageShareClick(val card: Card, val historyEntry: HistoryEntry) : HomeAction\n    data class PageOverflowClick(val card: Card, val pageSummary: PageSummary, val source: Int, val menuKey: String) : HomeAction\n    data class PageOverflowItemClick(val card: Card, val item: PageOverflowMenuItem, val historyEntry: HistoryEntry) : HomeAction\n    data object PageOverflowDismiss : HomeAction\n    data class NewsClick(val card: NewsCard, val newsItem: NewsItem) : HomeAction\n    data class ImageClick(val card: FeaturedImageCard) : HomeAction\n    data class ImageDownloadClick(val card: FeaturedImageCard) : HomeAction\n    data class ImageShareClick(val card: FeaturedImageCard) : HomeAction\n    data class LanguageSelected(val languageCode: String) : HomeAction\n    data object ManageLanguagesClick : HomeAction\n    data object TabClick : HomeAction\n    data object UpdateTabCount : HomeAction\n    data class CustomizeClick(val card: Card?) : HomeAction\n    data class CardImpression(val card: Card, val index: Int) : HomeAction\n    data class CardFooterClick(val card: Card) : HomeAction\n    data object NotificationClick : HomeAction\n    data object ManageModulesClick : HomeAction\n    data object ShuffleClick : HomeAction\n    data object PlacesTeaserClick : HomeAction\n    data object DiscoverTeaserClick : HomeAction\n    data object SeeAllRecommendationsClick : HomeAction\n    data class GameActionClick(val wikiGame: WikiGame) : HomeAction\n    data object GoToGamesHubClick : HomeAction\n    data object ReadAloudPlayClick : HomeAction\n    data object ReadAloudShowSurvey : HomeAction\n    data object ReadAloudShowInfo : HomeAction\n    data object ReadAloudReportIssue : HomeAction\n}","file":"app/src/main/java/org/wikipedia/feed/HomeAction.kt","kind":"interface","line":13,"members":{"CardFooterClick":[37,37],"CardImpression":[36,36],"CustomizeClick":[35,35],"DiscoverTeaserClick":[42,42],"GameActionClick":[44,44],"GoToGamesHubClick":[45,45],"HideCommunityCard":[18,18],"HideForYouCard":[19,19],"HideModule":[20,20],"ImageClick":[28,28],"ImageDownloadClick":[29,29],"ImageShareClick":[30,30],"LanguageSelected":[31,31],"LoadMoreCommunityContent":[16,16],"LoadMoreForYouContent":[17,17],"ManageLanguagesClick":[32,32],"ManageModulesClick":[39,39],"NewsClick":[27,27],"NotificationClick":[38,38],"PageBookmarkClick":[22,22],"PageClick":[21,21],"PageOverflowClick":[24,24],"PageOverflowDismiss":[26,26],"PageOverflowItemClick":[25,25],"PageShareClick":[23,23],"PlacesTeaserClick":[41,41],"ReadAloudPlayClick":[46,46],"ReadAloudReportIssue":[49,49],"ReadAloudShowInfo":[48,48],"ReadAloudShowSurvey":[47,47],"RefreshTab":[15,15],"SeeAllRecommendationsClick":[43,43],"SelectTab":[14,14],"ShuffleClick":[40,40],"TabClick":[33,33],"UpdateTabCount":[34,34]},"supers":[]},"HomeFragment":{"appearsIn":[["home","h-classes","Logic \u00b7 class diagram"],["home","h-sequence","Load more of the Community feed \u00b7 sequence"],["index","h-screens","Screens \u00b7 how the user moves"],["launch","h-sequence","First launch \u00b7 sequence"]],"code":"class HomeFragment : Fragment(), LinkPreviewDialog.LoadPageCallback {\n    private val viewModel: HomeViewModel by viewModels()\n    private val pageOverflowMenuViewModel: PageOverflowMenuViewModel by viewModels()\n    private val cardImpressions = mutableSetOf<String>()\n    private val instrument = TestKitchenAdapter.client.getInstrument(\"apps-home-feed\")\n        .startFunnel(\"home_feed\").also {\n            if (ReadAloudLeadSectionABTest().isTestActive()) {\n                it.setExperiment(TestKitchenAdapter.getExperiment(ReadAloudLeadSectionABTest()))\n            }\n        }\n\n    private val personalizationResultLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) {\n        if (it.resultCode == RESULT_OK) {\n            val tab = if (Prefs.homePreferenceSelection == HomePreferenceType.PERSONALIZED) HomeTab.FOR_YOU else HomeTab.COMMUNITY\n            selectTab(tab)\n        }\n    }\n\n    private val customizeInterestsLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) {\n        if (it.resultCode == RESULT_INTERESTS_UPDATED) {\n            Prefs.homeForYouModulesToday = \"\"\n            viewModel.refreshForYouContent()\n        }\n    }\n\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n\n        lifecycleScope.launch {\n            repeatOnLifecycle(Lifecycle.State.CREATED) {\n                viewModel.forYouNetworkLatency.collectLatest {\n                    if (it > 0) {\n                        instrument.submitInteraction(\"timing\", actionSource = \"for_you_latency\", actionContext = mapOf(\"latency\" to it))\n                    }\n                }\n            }\n        }\n\n        if (savedInstanceState == null) {\n            maybeShowExploreFeedUpdatePrompt()\n        }\n    }\n\n    override fun onCreateView(\n        inflater: LayoutInflater,\n        container: ViewGroup?,\n        savedInstanceState: Bundle?\n    ): View {\n        return ComposeView(requireActivity()).apply {\n            setContent {\n                val selectedTab by viewModel.selectedTab.collectAsState()\n                val wikiSite by viewModel.wikiSite.collectAsState()\n                val tabsState by viewModel.tabsState.collectAsState()\n                val notificationState by viewModel.unreadCount.collectAsState()\n                val forYouContentState by viewModel.forYouState.collectAsState()\n                val communityContentState by viewModel.communityState.collectAsState()\n                var swipeToExplorePromptShown by remember { mutableStateOf(Prefs.isHomeSwipeToExplorePromptShown) }\n                var showReadAloudSurveyDialog by remember { mutableStateOf(false) }\n\n                BaseTheme(currentTheme = if (selectedTab == HomeTab.FOR_YOU) Theme.BLACK else WikipediaApp.instance.currentTheme) {\n                    HomeScreen(\n                        wikiSite = wikiSite,\n                        languageState = WikipediaApp.instance.languageState,\n                        selectedTab = selectedTab,\n                        communityContentState = communityContentState,\n                        forYouContentState = forYouContentState,\n                        overflowMenuState = pageOverflowMenuViewModel.pageOverflowMenuState,\n                        savedInReadingListTitles = viewModel.savedInReadingListTitles.collectAsState().value,\n                        resolveForYouSavedState = { title ->\n                            AppDatabase.instance.readingListPageDao().findPageInAnyList(title) != null\n                        },\n                        tabsState = tabsState,\n                        notificationBellState = notificationState,\n                        onAction = {\n                            if (it is HomeAction.ReadAloudShowSurvey) {\n                                showReadAloudSurveyDialog = true\n                            } else {\n                                handleHomeAction(it, wikiSite, selectedTab)\n                            }\n                        }\n                    )\n\n                    if (selectedTab == HomeTab.FOR_YOU && !swipeToExplorePromptShown && forYouContentState.modules.isNotEmpty()) {\n                        val dismissSwipePrompt = {\n                            swipeToExplorePromptShown = true\n                            Prefs.isHomeSwipeToExplorePromptShown = true\n                        }\n                        WikipediaAlertDialog(\n                            title = stringResource(R.string.explore_feed_swipe_to_explore_prompt_title),\n                            titleModifier = Modifier.fillMaxWidth(),\n                            message = stringResource(R.string.explore_feed_swipe_to_explore_prompt_message),\n                            image = {\n                                Image(\n                                    painter = painterResource(R.drawable.swipe_gesture_illustration),\n                                    contentDescription = null,\n                                    modifier = Modifier.fillMaxWidth()\n                                )\n                            },\n                            confirmButtonText = stringResource(R.string.onboarding_got_it),\n                            onDismissRequest = dismissSwipePrompt,\n                            onConfirmButtonClick = dismissSwipePrompt\n                        )\n                    }\n\n                    if (showReadAloudSurveyDialog) {\n                        ReadAloudSurveyDialog(onDismissRequest = { showReadAloudSurveyDialog = false }, instrument)\n                    } else {\n                        if (ReadAloudSurveyDialog.shouldShow(byDate = true)) {\n                            showReadAloudSurveyDialog = true\n                        }\n                    }\n                }\n            }\n        }\n    }\n\n    override fun onResume() {\n        super.onResume()\n        val mainActivity = requireActivity() as? MainActivity\n        if (mainActivity?.isCurrentFragmentSelected(this) == true) {\n            mainActivity.onTabChanged(NavTab.HOME)\n        }\n        viewModel.updateTabCount()\n        viewModel.updateSelectedLanguageIfNeeded()\n        instrument.stopFunnel()\n        instrument.startFunnel(\"home_feed\")\n        refreshNotification()\n        maybeShowSurveyDialog()\n    }\n\n    fun getCurrentTab(): HomeTab {\n        return viewModel.selectedTab.value\n    }\n\n    override fun onPause() {\n        super.onPause()\n        cardImpressions.clear()\n    }\n\n    fun refreshNotification() {\n        viewModel.refreshUnreadNotificationCount()\n    }\n\n    fun updateLanguage(languageCode: String) {\n        viewModel.updateLanguage(languageCode)\n    }\n\n    fun selectTab(tab: HomeTab) {\n        viewModel.selectTab(tab)\n        (requireActivity() as? MainActivity)?.onTabChanged(NavTab.HOME)\n    }\n\n    private fun maybeShowExploreFeedUpdatePrompt() {\n        if (!Prefs.isInitialOnboardingEnabled && Prefs.isExploreFeedUpdatePromptShown.not()) {\n            personalizationResultLauncher.launch(ExploreFeedUpdatePromptActivity.newIntent(requireContext()))\n        }\n    }\n\n    private fun handleHomeAction(action: HomeAction, wikiSite: WikiSite, selectedTab: HomeTab) {\n        when (action) {\n            is HomeAction.SelectTab -> {\n                val card = action.card\n                if (card is EmptyCommunityCard || card is EmptyForYouCard) {\n                    instrument.submitInteraction(\"click\", actionSource = card.javaClass.simpleName, elementId = \"community_feed\")\n                }\n                selectTab(action.tab)\n            }\n            is HomeAction.RefreshTab -> {\n                Prefs.homeForYouModulesToday = \"\"\n                if (action.tab == HomeTab.COMMUNITY) {\n                    viewModel.refreshCommunityContent()\n                } else {\n                    viewModel.refreshForYouContent()\n                }\n            }\n            HomeAction.LoadMoreCommunityContent -> viewModel.loadCommunityContent()\n            HomeAction.LoadMoreForYouContent -> viewModel.loadForYouContent()\n            is HomeAction.HideCommunityCard -> {\n                val card = action.card\n                instrument.submitInteraction(\"click\", actionSource = card.javaClass.simpleName, actionSubtype = \"feed_overflow\", elementId = \"card_hide\")\n                viewModel.hideCommunityCard(card)\n                FeedbackUtil.makeSnackbar(requireActivity(), getString(R.string.menu_feed_card_dismissed))\n                    .setAction(getString(R.string.explore_feed_header_overflow_hide_module_message_action)) {\n                        instrument.submitInteraction(\"click\", actionSource = card.javaClass.simpleName, actionSubtype = \"feed_overflow\", elementId = \"undo_card_hide\")\n                        viewModel.restoreCommunityCard(card)\n                    }.show()\n            }\n            is HomeAction.HideForYouCard -> {\n                val card = action.card\n                instrument.submitInteraction(\"click\", actionSource = card.javaClass.simpleName, actionSubtype = \"feed_overflow\", elementId = \"card_hide\")\n                viewModel.hideForYouCard(card)\n                FeedbackUtil.makeSnackbar(requireActivity(), getString(R.string.menu_feed_card_dismissed))\n                    .setAction(getString(R.string.explore_feed_header_overflow_hide_module_message_action)) {\n                        instrument.submitInteraction(\"click\", actionSource = card.javaClass.simpleName, actionSubtype = \"feed_overflow\", elementId = \"undo_card_hide\")\n                        viewModel.restoreForYouCard(card)\n                    }.show()\n            }\n            is HomeAction.HideModule -> {\n                val moduleKey = action.moduleKey\n                instrument.submitInteraction(\"click\", actionSource = moduleKey, actionSubtype = \"feed_overflow\", elementId = \"module_hide\")\n                viewModel.hideModule(moduleKey)\n                FeedbackUtil.makeSnackbar(requireActivity(), getString(R.string.explore_feed_header_overflow_hide_module_message))\n                    .setAction(getString(R.string.explore_feed_header_overflow_hide_module_message_action)) {\n                        instrument.submitInteraction(\"click\", actionSource = moduleKey, actionSubtype = \"feed_overflow\", elementId = \"undo_module_hide\")\n                        viewModel.restoreModule(moduleKey)\n                    }.show()\n            }\n            is HomeAction.PageClick -> {\n                instrument.submitInteraction(\"click\", actionSource = action.card.javaClass.simpleName, elementId = \"article_open\", pageData = TestKitchenAdapter.getPageData(pageTitle = action.historyEntry.title))\n                (parentFragment as? MainFragment)?.onFeedSelectPage(action.historyEntry, false)\n            }\n            is HomeAction.PageBookmarkClick -> {\n                instrument.submitInteraction(\"click\", actionSource = action.card.javaClass.simpleName, elementId = \"article_save\", pageData = TestKitchenAdapter.getPageData(pageTitle = action.historyEntry.title))\n                SaveArticleSheetDialog.show(childFragmentManager, action.historyEntry.title)\n            }\n            is HomeAction.PageShareClick -> {\n                instrument.submitInteraction(\"click\", actionSource = action.card.javaClass.simpleName, elementId = \"article_share\", pageData = TestKitchenAdapter.getPageData(pageTitle = action.historyEntry.title))\n                ShareUtil.shareText(requireContext(), action.historyEntry.title)\n            }\n            is HomeAction.PageOverflowClick -> {\n                pageOverflowMenuViewModel.onPageOverflowClick(\n                    wikiSite = wikiSite,\n                    pageSummary = action.pageSummary,\n                    source = action.source,\n                    menuKey = action.menuKey\n                )\n            }\n            is HomeAction.PageOverflowItemClick -> {\n                val entry = action.historyEntry\n                val elementId = when (action.item) {\n                    PageOverflowMenuItem.OPEN_PAGE -> \"article_open\"\n                    PageOverflowMenuItem.OPEN_IN_NEW_TAB -> \"article_open_new_tab\"\n                    PageOverflowMenuItem.SAVE -> \"article_save\"\n                    PageOverflowMenuItem.SHARE -> \"article_share\"\n                    PageOverflowMenuItem.COPY_LINK -> \"article_copy_link\"\n                }\n                instrument.submitInteraction(\"click\", actionSource = action.card.javaClass.simpleName, actionSubtype = \"feed_item_overflow\", elementId = elementId, pageData = TestKitchenAdapter.getPageData(pageTitle = entry.title))\n                val mainFragment = parentFragment as? MainFragment\n                when (action.item) {\n                    PageOverflowMenuItem.OPEN_PAGE -> mainFragment?.onFeedSelectPage(entry, false)\n                    PageOverflowMenuItem.OPEN_IN_NEW_TAB -> {\n                        mainFragment?.onFeedSelectPage(entry, true)\n                        viewModel.updateTabCount(true)\n                    }\n                    PageOverflowMenuItem.SAVE -> mainFragment?.onFeedSavePage(entry)\n                    PageOverflowMenuItem.SHARE -> mainFragment?.onFeedSharePage(entry)\n                    PageOverflowMenuItem.COPY_LINK -> mainFragment?.onFeedCopyLink(entry)\n                }\n            }\n            HomeAction.PageOverflowDismiss -> {\n                pageOverflowMenuViewModel.dismissPageOverflowMenu()\n            }\n            is HomeAction.NewsClick -> {\n                val card = action.card\n                instrument.submitInteraction(\"click\", actionSource = card.javaClass.simpleName, elementId = card.javaClass.simpleName, actionContext = mapOf(\"index\" to card.news.indexOf(action.newsItem)))\n                (parentFragment as? MainFragment)?.onFeedNewsItemSelected(action.newsItem, wikiSite)\n            }\n            is HomeAction.ImageClick -> {\n                val card = action.card\n                instrument.submitInteraction(\"click\", actionSource = card.javaClass.simpleName, elementId = \"article_open\", pageData = TestKitchenAdapter.getPageData(pageTitle = card.featuredImage.toPageTitle()))\n                (parentFragment as? MainFragment)?.onFeaturedImageSelected(card.featuredImage)\n            }\n            is HomeAction.ImageShareClick -> {\n                val card = action.card\n                instrument.submitInteraction(\"click\", actionSource = card.javaClass.simpleName, elementId = \"share\", pageData = TestKitchenAdapter.getPageData(pageTitle = card.featuredImage.toPageTitle()))\n                (parentFragment as? MainFragment)?.onFeedShareImage(card.featuredImage, card.age)\n            }\n            is HomeAction.ImageDownloadClick -> {\n                val card = action.card\n                instrument.submitInteraction(\"click\", actionSource = card.javaClass.simpleName, elementId = \"download\", pageData = TestKitchenAdapter.getPageData(pageTitle = card.featuredImage.toPageTitle()))\n                (parentFragment as? MainFragment)?.onFeedDownloadImage(card.featuredImage)\n            }\n            is HomeAction.LanguageSelected -> {\n                instrument.submitInteraction(\"click\", \"language_menu\", elementId = \"language_change\", actionContext = mapOf(\"selected_tab\" to selectedTab.name, \"language_code\" to action.languageCode))\n                updateLanguage(action.languageCode)\n            }\n            HomeAction.ManageLanguagesClick -> {\n                instrument.submitInteraction(\"click\", \"language_menu\", elementId = \"manage_languages\", actionContext = mapOf(\"selected_tab\" to selectedTab.name))\n                requireActivity().startActivity(WikipediaLanguagesActivity.newIntent(requireContext(), invokeSource = InvokeSource.FEED))\n            }\n            is HomeAction.CustomizeClick -> {\n                val card = action.card\n                if (card != null) {\n                    instrument.submitInteraction(\"click\", actionSource = card.javaClass.simpleName,\n                        actionSubtype = if (card !is EmptyForYouCard) \"feed_overflow\" else null,\n                        elementId = \"feed_customize\")\n                }\n                if (card is DiscoverCard) {\n                    requireActivity().startActivity(RecommendedReadingListSettingsActivity.newIntent(requireContext()))\n                } else {\n                    customizeInterestsLauncher.launch(PersonalizationActivity.newIntent(requireContext(), showInterestsOnly = true))\n                }\n            }\n            HomeAction.TabClick -> {\n                requireActivity().startActivity(TabActivity.newIntent(requireActivity()))\n            }\n            HomeAction.UpdateTabCount -> {\n                viewModel.updateTabCount(false)\n            }\n            is HomeAction.CardImpression -> {\n                onCardImpression(action.card, action.index)\n            }\n            is HomeAction.CardFooterClick -> {\n                when (val card = action.card) {\n                    is TopReadCard -> {\n                        instrument.submitInteraction(\"click\", actionSource = card.javaClass.simpleName, elementId = \"more_top_read\")\n                        startActivity(TopReadArticlesActivity.newIntent(requireActivity(),\n                            TopReadCard(card.articles, card.age, wikiSite)\n                        ))\n                    }\n                    is OnThisDayCard -> {\n                        instrument.submitInteraction(\"click\", actionSource = card.javaClass.simpleName, elementId = \"more_on_this_day\")\n                        startActivity(OnThisDayActivity.newIntent(requireActivity(), card.age, -1, wikiSite, InvokeSource.ON_THIS_DAY_CARD_FOOTER))\n                    }\n                    is DidYouKnowCard -> {\n                        instrument.submitInteraction(\"click\", actionSource = card.javaClass.simpleName, elementId = \"more_did_you_know\")\n                        startActivity(DidYouKnowActivity.newIntent(requireActivity(), card.site, card.items))\n                    }\n                }\n            }\n            HomeAction.NotificationClick -> {\n                requireActivity().startActivity(NotificationActivity.newIntent(requireActivity()))\n            }\n            HomeAction.ManageModulesClick -> {\n                instrument.submitInteraction(\"click\", actionSource = \"feed_empty\", elementId = \"customize_feed\")\n                val intent = HomeFeedSettingsActivity.newIntent(\n                    context = requireContext(),\n                    startDestination = when (selectedTab) {\n                        HomeTab.COMMUNITY -> HomeFeedSettingsStartDestination.COMMUNITY_MODULES\n                        HomeTab.FOR_YOU -> HomeFeedSettingsStartDestination.FOR_YOU_MODULES\n                    }\n                )\n                requireActivity().startActivity(intent)\n            }\n            HomeAction.ShuffleClick -> {\n                instrument.submitInteraction(\"click\", actionSource = RandomCard::class.java.simpleName, elementId = \"random_card_shuffle_button\")\n                startActivity(RandomActivity.newIntent(requireActivity(), wikiSite, InvokeSource.FEED))\n            }\n            HomeAction.PlacesTeaserClick -> {\n                instrument.submitInteraction(\"click\", actionSource = PlacesOfInterestLocationPromptCard::class.java.simpleName, elementId = \"go_to_places\")\n                requireActivity().startActivity(PlacesActivity.newIntent(requireContext()))\n            }\n            HomeAction.DiscoverTeaserClick -> {\n                instrument.submitInteraction(\"click\", actionSource = DiscoverEnablePromptCard::class.java.simpleName, elementId = \"enable_discover_reading_list_button\")\n                requireActivity().startActivity(RecommendedReadingListOnboardingActivity.newIntent(requireContext()))\n            }\n            HomeAction.SeeAllRecommendationsClick -> {\n                instrument.submitInteraction(\"click\", actionSource = SeeAllRecommendationCard::class.java.simpleName, elementId = \"explore_all_recommendations_button\")\n                startActivity(ReadingListActivity.newIntent(requireContext(), readingListMode = ReadingListMode.RECOMMENDED))\n            }\n            is HomeAction.GameActionClick -> {\n                when (val wikiGame = action.wikiGame) {\n                    is WikiGame.OnThisDayGame -> {\n                        val gameStatus = when (wikiGame.state) {\n                            is OnThisDayCardGameState.Completed -> DailyGameHistory.GAME_COMPLETED\n                            is OnThisDayCardGameState.InProgress,\n                            is OnThisDayCardGameState.Preview -> DailyGameHistory.GAME_IN_PROGRESS\n                        }\n                        val elementId = when (wikiGame.state) {\n                            is OnThisDayCardGameState.Preview -> \"play_click\"\n                            is OnThisDayCardGameState.InProgress -> \"continue_click\"\n                            is OnThisDayCardGameState.Completed -> \"review_click\"\n                        }\n                        instrument.submitInteraction(\"click\", actionSource = WikiGameCard::class.java.simpleName, elementId = elementId, actionContext = mapOf(\"game\" to wikiGame.game.name))\n                        requireActivity().startActivity(OnThisDayGameActivity.newIntent(\n                            context = requireContext(),\n                            invokeSource = InvokeSource.FEED,\n                            wikiSite = wikiSite,\n                            gameStatus = gameStatus\n                        ))\n                    }\n                }\n            }\n            HomeAction.GoToGamesHubClick -> {\n                instrument.submitInteraction(\"click\", actionSource = GamesModulePromptCard::class.java.simpleName, elementId = \"go_to_games_hub\")\n                requireActivity().startActivity(GamesHubActivity.newIntent(requireContext(), InvokeSource.FEED))\n            }\n            HomeAction.ReadAloudPlayClick -> {\n                instrument.submitInteraction(\"click\", actionSource = ReadAloudLeadSectionCard::class.java.simpleName, elementId = \"play_pause\")\n            }\n            HomeAction.ReadAloudShowInfo -> {\n                instrument.submitInteraction(\"click\", actionSource = ReadAloudLeadSectionCard::class.java.simpleName, elementId = \"menu_about\")\n                UriUtil.visitInExternalBrowser(requireContext(), getString(R.string.read_aloud_lead_section_info_link).toUri())\n            }\n            HomeAction.ReadAloudReportIssue -> {\n                instrument.submitInteraction(\"click\", actionSource = ReadAloudLeadSectionCard::class.java.simpleName, elementId = \"menu_report_issue\")\n                FeedbackUtil.composeEmail(requireContext(),\n                    subject = getString(R.string.read_aloud_lead_section_report_subject),\n                    body = getString(R.string.read_aloud_lead_section_report_body))\n            }\n            else -> {\n            }\n        }\n    }\n\n    private fun onCardImpression(card: Card, index: Int) {\n        if (cardImpressions.add(card.hideKey)) {\n            instrument.submitInteraction(\n                \"impression\",\n                actionSource = card.javaClass.simpleName,\n                actionContext = mapOf(\"card_index\" to index)\n            )\n        }\n    }\n\n    private fun maybeShowSurveyDialog() {\n        val endDate = LocalDate.of(2026, 8, 14)\n        val minVisits = 4\n\n        // don't show the survey if the user has not seen other dialogs or prompts that can be shown on the feed\n        if (!Prefs.isExploreFeedUpdatePromptShown) {\n            return\n        }\n\n        if (Prefs.homeFeedSurveyShown || LocalDate.now().isAfter(endDate)) {\n            return\n        }\n\n        if (Prefs.exploreFeedVisitCount < minVisits) {\n            return\n        }\n\n        Prefs.homeFeedSurveyShown = true\n        SurveyDialog.showHomeFeedFeedbackDialog(\n            activity = requireActivity(),\n            onImpression = {\n                instrument.submitInteraction(\n                    action = \"impression\",\n                    actionSource = \"home_feed_feedback\"\n                )\n            },\n            onCancel = {\n                instrument.submitInteraction(\n                    action = \"click\",\n                    actionSource = \"home_feed_feedback\",\n                    elementId = \"feedback_cancel\"\n                )\n            },\n            onSubmit = { feedbackOption, feedbackText ->\n                instrument.submitInteraction(\n                    action = \"click\",\n                    actionSource = \"home_feed_feedback\",\n                    elementId = \"feedback_submit\",\n                    actionContext = buildMap {\n                        feedbackOption?.let { put(\"score\", it) }\n                        put(\"text\", feedbackText)\n                    }\n                )\n            }\n        )\n    }\n\n    override fun onLinkPreviewLoadPage(title: PageTitle, entry: HistoryEntry, inNewTab: Boolean) {\n        if (inNewTab) {\n            (parentFragment as? MainFragment)?.onFeedSelectPage(entry, true)\n            viewModel.updateTabCount(true)\n        } else {\n            (parentFragment as? MainFragment)?.onFeedSelectPage(entry, false)\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/feed/HomeFragment.kt","kind":"class","line":92,"members":{"cardImpressions":[95,95],"customizeInterestsLauncher":[110,115],"getCurrentTab":[222,224],"handleHomeAction":[250,485],"instrument":[96,101],"maybeShowExploreFeedUpdatePrompt":[244,248],"maybeShowSurveyDialog":[497,542],"onCardImpression":[487,495],"onCreate":[117,133],"onCreateView":[135,206],"onLinkPreviewLoadPage":[544,551],"onPause":[226,229],"onResume":[208,220],"pageOverflowMenuViewModel":[94,94],"personalizationResultLauncher":[103,108],"refreshNotification":[231,233],"selectTab":[239,242],"updateLanguage":[235,237],"viewModel":[93,93]},"shot":"shots/code/HomeFragment.jpg","supers":["Fragment()","LinkPreviewDialog.LoadPageCallback"]},"HomeScreen":{"appearsIn":[["home","h-widgets","Screen \u00b7 composition"]],"code":"@Composable\nfun HomeScreen(\n    wikiSite: WikiSite,\n    languageState: AppLanguageState? = null,\n    selectedTab: HomeTab,\n    communityContentState: CommunityContentState,\n    forYouContentState: ForYouContentState,\n    overflowMenuState: PageOverflowMenuViewModel.PageOverflowMenuState? = null,\n    savedInReadingListTitles: Set<String> = emptySet(),\n    resolveForYouSavedState: suspend (PageTitle) -> Boolean = { false },\n    tabsState: TabsState,\n    notificationBellState: NotificationBellState,\n    onAction: (HomeAction) -> Unit = {}\n) {\n    val context = LocalContext.current\n    val topInset = if (context is MainActivity) {\n        DimenUtil.roundedPxToDp((context.getStatusBarInsets()?.top ?: 0).toFloat())\n    } else 64\n    val pullToRefreshState = rememberPullToRefreshState()\n    val isRefreshing = pullToRefreshState.isAnimating && (communityContentState.isInitialLoading || forYouContentState.isInitialLoading)\n\n    PullToRefreshBox(\n        modifier = Modifier.fillMaxSize(),\n        state = pullToRefreshState,\n        isRefreshing = isRefreshing,\n        onRefresh = { onAction(HomeAction.RefreshTab(selectedTab)) },\n        indicator = {\n            Indicator(\n                modifier = Modifier.align(Alignment.TopCenter),\n                isRefreshing = isRefreshing,\n                containerColor = WikipediaTheme.colors.paperColor,\n                color = WikipediaTheme.colors.progressiveColor,\n                state = pullToRefreshState\n            )\n        }\n    ) {\n        Box(\n            modifier = Modifier.fillMaxSize()\n        ) {\n            when (selectedTab) {\n                HomeTab.COMMUNITY -> {\n                    Column(\n                        modifier = Modifier\n                            .align(Alignment.TopCenter)\n                            .fillMaxSize()\n                            .background(WikipediaTheme.colors.paperColor)\n                    ) {\n                        HomeToolbar(\n                            topInset = topInset,\n                            tabsState = tabsState,\n                            onTabClick = { onAction(HomeAction.TabClick) },\n                            onUpdateTabCount = { onAction(HomeAction.UpdateTabCount) },\n                            notificationBellState = notificationBellState,\n                            onNotificationClick = { onAction(HomeAction.NotificationClick) }\n                        )\n\n                        HomeTabBar(\n                            modifier = Modifier.padding(top = 8.dp),\n                            wikiSite = wikiSite,\n                            selectedTab = selectedTab,\n                            languageState = languageState,\n                            onSelectTab = { tab, card -> onAction(HomeAction.SelectTab(tab, card)) },\n                            onLanguageSelected = { onAction(HomeAction.LanguageSelected(it)) },\n                            onManageLanguagesClick = { onAction(HomeAction.ManageLanguagesClick) }\n                        )\n\n                        CommunityContentTab(\n                            modifier = Modifier.weight(1f),\n                            wikiSite = wikiSite,\n                            state = communityContentState,\n                            overflowMenuState = overflowMenuState,\n                            savedInReadingListTitles = savedInReadingListTitles,\n                            onAction = onAction\n                        )\n                    }\n                }\n\n                HomeTab.FOR_YOU -> {\n                    ForYouContentTab(\n                        topInset = topInset,\n                        state = forYouContentState,\n                        wikiSite = wikiSite,\n                        resolveSavedState = resolveForYouSavedState,\n                        onAction = onAction\n                    )\n\n                    // Floating toolbar with gradient scrim, wordmark, and tab selector.\n                    Column(modifier = Modifier\n                        .align(Alignment.TopCenter)\n                        .fillMaxWidth()) {\n                        Box(\n                            modifier = Modifier\n                                .fillMaxWidth()\n                                .background(Color.Black.copy(alpha = 0.80f))\n                        ) {\n                            HomeToolbar(\n                                topInset = topInset,\n                                tabsState = tabsState,\n                                onTabClick = { onAction(HomeAction.TabClick) },\n                                onUpdateTabCount = { onAction(HomeAction.UpdateTabCount) },\n                                notificationBellState = notificationBellState,\n                                onNotificationClick = { onAction(HomeAction.NotificationClick) }\n                            )\n                        }\n                        Box(\n                            modifier = Modifier\n                                .fillMaxWidth()\n                                .background(\n                                    Brush.verticalGradient(\n                                        colorStops = arrayOf(\n                                            0.0f to Color.Black.copy(alpha = 0.80f),\n                                            0.18f to Color.Black.copy(alpha = 0.64f),\n                                            0.38f to Color.Black.copy(alpha = 0.40f),\n                                            0.58f to Color.Black.copy(alpha = 0.20f),\n                                            0.76f to Color.Black.copy(alpha = 0.08f),\n                                            0.90f to Color.Black.copy(alpha = 0.02f),\n                                            1.0f to Color.Transparent\n                                        )\n                                    )\n                                )\n                        ) {\n                            HomeTabBar(\n                                modifier = Modifier.padding(top = 8.dp, bottom = 64.dp),\n                                wikiSite = wikiSite,\n                                selectedTab = selectedTab,\n                                languageState = languageState,\n                                onSelectTab = { tab, card -> onAction(HomeAction.SelectTab(tab, card)) },\n                                onLanguageSelected = { onAction(HomeAction.LanguageSelected(it)) },\n                                onManageLanguagesClick = { onAction(HomeAction.ManageLanguagesClick) }\n                            )\n                        }\n                    }\n                }\n            }\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/feed/HomeScreen.kt","kind":"composable function","line":66,"members":{},"shot":"shots/code/HomeScreen.jpg","supers":[]},"HomeTab":{"appearsIn":[["home","h-classes","Logic \u00b7 class diagram"]],"code":"enum class HomeTab { COMMUNITY, FOR_YOU }","file":"app/src/main/java/org/wikipedia/feed/HomeViewModel.kt","kind":"enum","line":95,"members":{"COMMUNITY":[95,95],"FOR_YOU":[95,95]},"supers":[]},"HomeTabBar":{"appearsIn":[["home","h-widgets","Screen \u00b7 composition"]],"code":"@Composable\nfun HomeTabBar(\n    modifier: Modifier,\n    wikiSite: WikiSite,\n    selectedTab: HomeTab,\n    languageState: AppLanguageState? = null,\n    onSelectTab: (HomeTab, Card?) -> Unit = { _, _ -> },\n    onLanguageSelected: (String) -> Unit,\n    onManageLanguagesClick: () -> Unit\n) {\n    Row(\n        modifier = modifier\n            .fillMaxWidth()\n            .padding(horizontal = 8.dp, vertical = 8.dp),\n        horizontalArrangement = Arrangement.Start,\n        verticalAlignment = Alignment.CenterVertically\n    ) {\n        Row(\n            modifier = Modifier.weight(1f)\n        ) {\n            HomeTab.entries.forEach { tab ->\n                val isSelected = tab == selectedTab\n                val label = when (tab) {\n                    HomeTab.COMMUNITY -> LocalContext.current.getString(wikiSite.languageCode, R.string.explore_feed_community_tab_label)\n                    HomeTab.FOR_YOU -> LocalContext.current.getString(wikiSite.languageCode, R.string.explore_feed_for_you_tab_label)\n                }\n                Column(\n                    horizontalAlignment = Alignment.CenterHorizontally,\n                    modifier = Modifier\n                        .width(IntrinsicSize.Max)\n                        .clickable { onSelectTab(tab, null) }\n                        .padding(horizontal = 12.dp, vertical = 8.dp)\n                ) {\n                    Text(\n                        text = label,\n                        color = if (selectedTab == HomeTab.FOR_YOU) WikipediaTheme.colors.primaryColor else if (isSelected) WikipediaTheme.colors.progressiveColor else WikipediaTheme.colors.primaryColor,\n                        style = MaterialTheme.typography.titleSmall\n                    )\n                    Spacer(modifier = Modifier.height(4.dp))\n                    Box(\n                        modifier = Modifier\n                            .fillMaxWidth()\n                            .height(3.dp)\n                            .clip(RoundedCornerShape(1.5.dp))\n                            .background(\n                                if (isSelected) {\n                                    if (selectedTab == HomeTab.FOR_YOU) WikipediaTheme.colors.primaryColor\n                                    else WikipediaTheme.colors.progressiveColor\n                                } else Color.Transparent\n                            )\n                    )\n                }\n            }\n        }\n        LanguageDropDownMenu(\n            selectedLanguageCode = wikiSite.languageCode,\n            onLanguageSelected = { onLanguageSelected(it) },\n            onManageLanguagesClick = { onManageLanguagesClick() },\n            languageState = languageState\n        )\n    }\n}","file":"app/src/main/java/org/wikipedia/feed/HomeScreen.kt","kind":"composable function","line":272,"members":{},"supers":[]},"HomeToolbar":{"appearsIn":[["home","h-widgets","Screen \u00b7 composition"]],"code":"@Composable\nfun HomeToolbar(\n    topInset: Int,\n    tabsState: TabsState,\n    notificationBellState: NotificationBellState,\n    onTabClick: () -> Unit,\n    onUpdateTabCount: () -> Unit,\n    onNotificationClick: () -> Unit\n) {\n    Row(\n        modifier = Modifier.fillMaxWidth()\n    ) {\n        Image(\n            painter = painterResource(R.drawable.feed_header_wordmark),\n            contentDescription = null,\n            colorFilter = ColorFilter.tint(WikipediaTheme.colors.primaryColor),\n            contentScale = ContentScale.FillWidth,\n            modifier = Modifier\n                .statusBarsPadding()\n                .padding(start = 20.dp, top = (topInset + 16).dp)\n                .width(128.dp)\n        )\n        Spacer(modifier = Modifier.weight(1f))\n\n        val actionButtonModifier = Modifier\n            .statusBarsPadding()\n            .padding(top = topInset.dp)\n            .size(48.dp)\n\n        if (tabsState.count > 0) {\n            IconButton(\n                modifier = actionButtonModifier,\n                onClick = { onTabClick() }\n            ) {\n                TabsBox(\n                    modifier = Modifier\n                        .width(21.dp)\n                        .height(20.dp)\n                        .then(\n                            if (tabsState.pulse) {\n                                Modifier.pulse(\n                                    durationMillis = 300,\n                                    toScale = 1.25f,\n                                    onCompleted = {\n                                        onUpdateTabCount()\n                                    }\n                                )\n                            } else {\n                                Modifier\n                            }),\n                    backgroundColor = Color.Transparent,\n                    count = tabsState.count\n                )\n            }\n        }\n        if (notificationBellState.canShow) {\n            NotificationBell(\n                modifier = actionButtonModifier,\n                unreadCount = notificationBellState.unreadCount,\n                onClick = onNotificationClick\n            )\n        }\n        if (tabsState.count == 0 && !notificationBellState.canShow) {\n            Spacer(modifier = actionButtonModifier)\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/feed/HomeScreen.kt","kind":"composable function","line":204,"members":{},"supers":[]},"HomeViewModel":{"appearsIn":[["home","h-classes","Logic \u00b7 class diagram"],["home","h-sequence","Load more of the Community feed \u00b7 sequence"]],"code":"class HomeViewModel : ViewModel() {\n    private val _wikiSite = MutableStateFlow(WikiSite.forLanguageCode(Prefs.homeLanguageCode))\n    val wikiSite = _wikiSite.asStateFlow()\n\n    private val _selectedTab = MutableStateFlow(\n        if (Prefs.homePreferenceSelection == HomePreferenceType.PERSONALIZED) HomeTab.FOR_YOU else HomeTab.COMMUNITY\n    )\n    val selectedTab = _selectedTab.asStateFlow()\n\n    private val _communityState = MutableStateFlow(CommunityContentState())\n    val communityState = combine(\n        _communityState,\n        SettingsRepository.hiddenModules,\n        SettingsRepository.hiddenCards\n    ) { state, hiddenModules, hiddenCards ->\n        val visibleItems = state.cards\n            .filterNot { hiddenModules.contains(it.moduleKey()) }\n            .filterNot { hiddenCards.contains(it.hideKey) }\n        val hasContent = visibleItems.any { it !is DayHeaderCard }\n        val areAllModulesHidden = CommunityModuleType.entries.all { hiddenModules.contains(it.name) }\n        val emptyState = when {\n            areAllModulesHidden -> FeedEmptyState.ALL_MODULES_HIDDEN\n            !state.isInitialLoading && state.error == null && !hasContent -> FeedEmptyState.NO_DATA\n            else -> null\n        }\n        state.copy(cards = visibleItems, emptyState = emptyState)\n    }.stateIn(viewModelScope, SharingStarted.WhileSubscribed(MAX_STOP_TIMEOUT_MILLIS), CommunityContentState())\n\n    /**\n     * The Places of Interest module is loaded differently from the other \"For you\" modules, because it depends on location permission\n     * and the user's saved location from Places. So it lives in its own flow that reacts to those changes directly.\n     * Whenever the saved location or the feed language changes, we rebuild just this module (emitting a loading\n     * placeholder first when permission is granted) rather than reloading the entire tab. The result is merged into\n     * forYouState and sorted into its usual position by using ForYouModuleType enum ordinal.\n     */\n    @OptIn(ExperimentalCoroutinesApi::class)\n    private val placesModule: StateFlow<ForYouModule.PlacesOfInterest?> =\n        combine(Prefs.placesLastLocationFlow, _wikiSite) { _, _ -> }\n        .transformLatest {\n            if (hasLocationPermission()) {\n                emit(ForYouModule.PlacesOfInterest(age = 0, index = 0, cards = emptyList(), isLoading = true, hasLocationPermission = true))\n            }\n            emit(buildPlacesModule())\n        }\n        .catch {\n            L.e(it)\n            emit(null)\n        }\n        .stateIn(\n            viewModelScope,\n            SharingStarted.WhileSubscribed(MAX_STOP_TIMEOUT_MILLIS),\n            null\n        )\n\n    /**\n     * The Discover module (recommended reading list) loads independently of the batched \"For you\"\n     * modules, like Places. It reacts to the Discover settings (enabled state, article count, source, update frequency)\n     * and to NewRecommendedReadingListEvent posted when a new list is generated by RecommendedReadingListTask or the settings screen.\n     * On each trigger it emits a loading placeholder, then the module read from the local\n     * recommended pages. The result is merged into forYouState and sorted into its usual position by\n     * ForYouModuleType enum ordinal.\n     */\n    @OptIn(ExperimentalCoroutinesApi::class)\n    private val discoverModule: StateFlow<ForYouModule.Discover?> =\n        merge(\n            Prefs.observeKeys(\n                R.string.preference_key_recommended_reading_list_enabled,\n                R.string.preference_key_recommended_reading_list_articles_number,\n                R.string.preference_key_recommended_reading_list_source,\n                R.string.preference_key_recommended_reading_list_update_frequency\n            ),\n            FlowEventBus.events.filterIsInstance<NewRecommendedReadingListEvent>().map { }\n        )\n        .transformLatest {\n            if (Prefs.isRecommendedReadingListEnabled) {\n                emit(ForYouModule.Discover(age = 0, index = 0, cards = emptyList(), isEnabled = true, isLoading = true))\n            }\n            emit(buildDiscoverModule())\n        }\n        .catch {\n            L.e(it)\n            emit(null)\n        }\n        .stateIn(\n            viewModelScope,\n            SharingStarted.WhileSubscribed(MAX_STOP_TIMEOUT_MILLIS),\n            null\n        )\n\n    /**\n     * The Games module is loaded reactively, like Places, because its content should reflect live game progress.\n     * We observe today's game as a Room Flow in [DailyGameHistory] DB, so every write during play re-emits and rebuilds the\n     * module, moving the card through Preview -> InProgress -> Completed without a manual feed refresh.\n     */\n    @OptIn(ExperimentalCoroutinesApi::class)\n    private val gameModule: StateFlow<ForYouModule.Games?> =\n        _wikiSite.flatMapLatest { site ->\n            val supportedGames = getSupportedGames(site.languageCode)\n            // short-circuit if no games are supported for this language\n            if (supportedGames.isEmpty()) {\n                return@flatMapLatest flowOf(null)\n            }\n            val today = LocalDate.now()\n            AppDatabase.instance.dailyGameHistoryDao().findGameHistoryByDateFlow(\n                gameName = WikiGames.WHICH_CAME_FIRST.ordinal,\n                language = site.languageCode,\n                year = today.year,\n                month = today.monthValue,\n                day = today.dayOfMonth\n            )\n            .transformLatest<DailyGameHistory?, ForYouModule.Games?> {\n                emit(ForYouModule.Games(age = 0, index = 0, cards = emptyList(), isLoading = true))\n                emit(buildGameModule(supportedGames))\n            }\n        }\n        .catch {\n            L.e(it)\n            emit(null)\n        }\n        .stateIn(\n            viewModelScope,\n            SharingStarted.WhileSubscribed(MAX_STOP_TIMEOUT_MILLIS),\n            null\n        )\n\n    // Combine the reactive modules first so the outer combine stays within the 5-flow typed overloads.\n    private val reactiveModules = combine(placesModule, discoverModule, gameModule) { places, discover, game ->\n        listOfNotNull(places, discover, game)\n    }\n\n    private val _forYouState = MutableStateFlow(ForYouContentState())\n    val forYouState = combine(\n        _forYouState,\n        SettingsRepository.hiddenModules,\n        SettingsRepository.hiddenCards,\n        reactiveModules\n    ) { state, hiddenModules, hiddenCards, reactiveModules ->\n        val visibleItems = (state.modules + reactiveModules)\n            .sortedBy { ForYouModuleType.valueOf(it.moduleKey()).ordinal }\n            .filterNot { hiddenModules.contains(it.moduleKey()) }\n            .mapNotNull { module ->\n                val visibleCards = module.cards.filterNot { hiddenCards.contains(it.hideKey) }\n                // only drop module when it has cards, and they are all hidden, not when it is empty to begin with.\n                if (module.cards.isNotEmpty() && visibleCards.isEmpty()) null else module.withCards(visibleCards)\n            }\n        val areAllModulesHidden = ForYouModuleType.entries().all { hiddenModules.contains(it.key) }\n        val isInterestModuleHidden = hiddenModules.contains(ForYouModuleType.BASED_ON_INTEREST.name)\n        val emptyState = when {\n            areAllModulesHidden -> FeedEmptyState.ALL_MODULES_HIDDEN\n            !state.isInitialLoading && state.error == null && visibleItems.isEmpty() -> FeedEmptyState.NO_DATA\n            else -> null\n        }\n        state.copy(\n            modules = visibleItems,\n            emptyState = emptyState,\n            isInterestModuleHidden = isInterestModuleHidden\n        )\n    }.stateIn(viewModelScope, SharingStarted.WhileSubscribed(MAX_STOP_TIMEOUT_MILLIS), ForYouContentState())\n\n    // \"age\" in days from today. 0 = today, 1 = yesterday, etc.\n    private var nextCommunityAge = 0\n\n    // Batch counter for \"For you\" recommendations.\n    private var forYouBatchIndex = 0\n\n    private val _tabsState = MutableStateFlow(TabsState(WikipediaApp.instance.tabCount, pulse = false))\n    val tabsState = _tabsState.asStateFlow()\n\n    // Holds the API titles of Community-tab articles currently in the feed, to be queried whether they are saved in a reading list.\n    // The \"For you\" tab does not contribute here; its cards resolve saved state lazily on overflow-menu tap (see resolveForYouSavedState in HomeFragment).\n    private val _savedInReadingApiTitles = MutableStateFlow<List<String>>(emptyList())\n\n    // Derives saved state by asking Room only about those titles that we want to monitor.\n    // flatMapLatest restarts the DB observation whenever _savedInReadingApiTitles changes.\n    @OptIn(ExperimentalCoroutinesApi::class)\n    val savedInReadingListTitles: StateFlow<Set<String>> = _savedInReadingApiTitles\n        .flatMapLatest { titles ->\n            if (titles.isEmpty()) flowOf(emptySet())\n            else AppDatabase.instance.readingListPageDao()\n                .observeSavedApiTitles(\n                    wikiSite.value.languageCode,\n                    titles,\n                    ReadingListPage.STATUS_QUEUE_FOR_DELETE\n                )\n                .map { it.toSet() }\n        }\n        .catch {\n            L.e(it)\n            emit(emptySet())\n        }\n        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(MAX_STOP_TIMEOUT_MILLIS), emptySet())\n\n    private val communityHandler = CoroutineExceptionHandler { _, throwable ->\n        _communityState.value = _communityState.value.copy(\n            isInitialLoading = false,\n            isLoadingMore = false,\n            error = throwable\n        )\n    }\n\n    private val forYouHandler = CoroutineExceptionHandler { _, throwable ->\n        _forYouState.value = _forYouState.value.copy(\n            isInitialLoading = false,\n            isLoadingMore = false,\n            error = throwable\n        )\n    }\n\n    private val _unreadCount = MutableStateFlow(NotificationBellState())\n    val unreadCount = _unreadCount.asStateFlow()\n\n    private val _forYouNetworkLatency = MutableStateFlow(0L)\n    val forYouNetworkLatency = _forYouNetworkLatency.asStateFlow()\n\n    init {\n        viewModelScope.launch {\n            SettingsRepository.migrateLegacyHiddenCards()\n        }\n        viewModelScope.launch {\n            combine(_selectedTab, _wikiSite) { tab, site -> tab to site }\n            .distinctUntilChanged()\n            .collect { (tab, site) ->\n                ensureContentLoaded(tab, site)\n            }\n        }\n    }\n\n    fun refreshCommunityContent() {\n        nextCommunityAge = 0\n        _communityState.update { CommunityContentState() }\n        loadCommunityContent()\n    }\n\n    fun refreshForYouContent() {\n        forYouBatchIndex = 0\n        _forYouState.update { ForYouContentState() }\n        loadForYouContent()\n    }\n\n    fun selectTab(tab: HomeTab) {\n        _selectedTab.value = tab\n    }\n\n    private fun ensureContentLoaded(tab: HomeTab, site: WikiSite) {\n        when (tab) {\n            HomeTab.COMMUNITY -> {\n                if (_communityState.value.wikiSite != site) {\n                    refreshCommunityContent()\n                } else if (_communityState.value.cards.isEmpty() && !_communityState.value.isInitialLoading) {\n                    loadCommunityContent()\n                }\n            }\n            HomeTab.FOR_YOU -> {\n                if (_forYouState.value.wikiSite != site) {\n                    refreshForYouContent()\n                } else if (_forYouState.value.modules.isEmpty() && !_forYouState.value.isInitialLoading) {\n                    loadForYouContent()\n                }\n            }\n        }\n    }\n\n    fun updateLanguage(langCode: String) {\n        Prefs.homeLanguageCode = langCode\n        _wikiSite.value = WikiSite.forLanguageCode(langCode)\n    }\n\n    fun updateTabCount(pulse: Boolean = false) {\n        _tabsState.value = TabsState(WikipediaApp.instance.tabCount, pulse)\n    }\n\n    fun updateSelectedLanguageIfNeeded() {\n        if (!WikipediaApp.instance.languageState.appLanguageCodes.contains(wikiSite.value.languageCode)) {\n            updateLanguage(WikipediaApp.instance.languageState.appLanguageCode)\n        }\n    }\n\n    /**\n     * Loads the next day's community content (today on first call, then progressively older).\n     * Safe to call as a retry \u2014 the age only advances after a successful fetch.\n     */\n    fun loadCommunityContent() {\n        if (_communityState.value.isInitialLoading || _communityState.value.isLoadingMore) return\n\n        viewModelScope.launch(communityHandler) {\n            val isInitial = _communityState.value.cards.isEmpty()\n            _communityState.value = _communityState.value.copy(\n                wikiSite = wikiSite.value,\n                isInitialLoading = isInitial,\n                isLoadingMore = !isInitial,\n                error = null\n            )\n\n            val age = nextCommunityAge\n            val date = LocalDate.now().minusDays(nextCommunityAge.toLong())\n            val content = ServiceFactory.getRest(wikiSite.value)\n                .getFeedFeatured(date.year.toString(), \"%02d\".format(Locale.ROOT, date.monthValue), \"%02d\".format(Locale.ROOT, date.dayOfMonth), wikiSite.value.languageCode)\n\n            // Construct Card objects based on the day's content\n            val cardsForDay = buildList {\n                content.tfa?.let {\n                    add(FeaturedArticleCard(it, age, wikiSite.value))\n                }\n                content.topRead?.let {\n                    add(TopReadCard(it, age, wikiSite.value))\n                }\n                content.dyk?.let {\n                    add(DidYouKnowCard(it, date.toString(), wikiSite.value))\n                }\n                if (!content.news.isNullOrEmpty()) {\n                    add(NewsCard(content.news, age, wikiSite.value))\n                }\n                if (!content.onthisday.isNullOrEmpty()) {\n                    add(OnThisDayCard(content.onthisday.take(2), age, wikiSite.value))\n                }\n                content.potd?.let {\n                    add(FeaturedImageCard(it, age, wikiSite.value))\n                }\n            }.toMutableList()\n            if (cardsForDay.isNotEmpty()) {\n                cardsForDay.add(0, DayHeaderCard(age))\n            }\n\n            // Advance age only after success, so retry on failure re-fetches the same day.\n            nextCommunityAge = age + 1\n\n            _communityState.value = _communityState.value.copy(\n                cards = _communityState.value.cards + cardsForDay,\n                isInitialLoading = false,\n                isLoadingMore = false,\n                error = null,\n                canLoadMore = true\n            )\n\n            _savedInReadingApiTitles.value = _communityState.value.cards.filterIsInstance<FeaturedArticleCard>()\n                .map { it.page.apiTitle }\n        }\n    }\n\n    /**\n     * Loads the next batch of personalized recommendations for the \"For you\" tab.\n     * Safe to call as a retry \u2014 the batch index only advances after a successful fetch.\n     */\n    fun loadForYouContent() {\n        if (_forYouState.value.isInitialLoading || _forYouState.value.isLoadingMore) return\n\n        viewModelScope.launch(forYouHandler) {\n            val isInitial = _forYouState.value.modules.isEmpty()\n            _forYouState.value = _forYouState.value.copy(\n                wikiSite = wikiSite.value,\n                isInitialLoading = isInitial,\n                isLoadingMore = !isInitial,\n                error = null\n            )\n\n            val newModules = fetchForYouModules(forYouBatchIndex)\n\n            // Advance batch index only after success.\n            forYouBatchIndex++\n\n            _forYouState.value = _forYouState.value.copy(\n                modules = _forYouState.value.modules + newModules,\n                isInitialLoading = false,\n                isLoadingMore = false,\n                error = null\n            )\n        }\n    }\n\n    fun hideCommunityCard(card: Card) {\n        viewModelScope.launch {\n            SettingsRepository.addHiddenCard(card.hideKey)\n        }\n    }\n\n    fun restoreCommunityCard(card: Card) {\n        viewModelScope.launch {\n            SettingsRepository.removeHiddenCard(card.hideKey)\n        }\n    }\n\n    fun hideForYouCard(card: ForYouCard) {\n        viewModelScope.launch {\n            SettingsRepository.addHiddenCard(card.hideKey)\n        }\n    }\n\n    fun restoreForYouCard(card: ForYouCard) {\n        viewModelScope.launch {\n            SettingsRepository.removeHiddenCard(card.hideKey)\n        }\n    }\n\n    fun hideModule(moduleKey: String) {\n        viewModelScope.launch {\n            SettingsRepository.addHiddenModule(moduleKey)\n        }\n    }\n\n    fun restoreModule(moduleKey: String) {\n        viewModelScope.launch {\n            SettingsRepository.removeHiddenModule(moduleKey)\n        }\n    }\n\n    private suspend fun fetchForYouModules(age: Int): List<ForYouModule> {\n        val modules = mutableListOf<ForYouModule>()\n        val hiddenCards = SettingsRepository.hiddenCards.first()\n        var forYouCollectionSaved = ForYouCollectionSaved()\n\n        try {\n            withContext(Dispatchers.Default) {\n                forYouCollectionSaved = JsonUtil.decodeFromString<ForYouCollectionSaved>(Prefs.homeForYouModulesToday)!!\n            }\n        } catch (e: Exception) {\n            L.e(\"Failed to load modules from cache.\")\n        }\n\n        val currentDateTime = LocalDateTime.now()\n        val currentWikiSite = wikiSite.value\n        val languageCode = currentWikiSite.languageCode\n        val cachedModulesByLanguage = if (forYouCollectionSaved.dateTime?.toLocalDate() == currentDateTime.toLocalDate()) {\n            forYouCollectionSaved.modulesPerLanguage\n        } else {\n            emptyMap()\n        }\n\n        val cachedModules = cachedModulesByLanguage[languageCode]\n        if (cachedModules != null) {\n            L.d(\"Loading modules from cache...\")\n            return cachedModules.mapNotNull { module ->\n                val filteredCards = module.cards.filterNot { hiddenCards.contains(it.hideKey) }\n                if (filteredCards.isEmpty()) {\n                    null\n                } else {\n                    module.withCards(filteredCards)\n                }\n            }\n        }\n\n        L.d(\"Loading modules from network...\")\n        val seedEntries = getRandomSeedEntries(languageCode, limit = 2)\n        val becauseYouReadSeed = seedEntries.getOrNull(0)\n        val continueReadingSeed = seedEntries.getOrNull(1)\n        val startMillis = System.currentTimeMillis()\n\n        coroutineScope {\n            // --- Interests ---\n\n            val interestTopics = AppDatabase.instance.topicInterestDao().getAllRandom().distinctBy { it.topicId }.take(5)\n            val interestTopicCalls = interestTopics.map { topic ->\n                async(Dispatchers.IO) {\n                    val articleTopic = ArticleTopics.all.find { it.topicId == topic.topicId }\n                    InterestSelectionRepository.getArticlesByTopic(currentWikiSite, articleTopic?.queryTopicId ?: topic.topicId).map {\n                        // TODO: filter items that have already been suggested.\n                        BasedOnInterestCard(it, interestTopic = topic)\n                    }.filterNot { hiddenCards.contains(it.hideKey) }.take(4)\n                }\n            }\n\n            val interestArticles = AppDatabase.instance.articleInterestDao().getAllRandom(languageCode).take(5)\n            val interestArticleCalls = interestArticles.map { article ->\n                async(Dispatchers.IO) {\n                    val searchTerm = StringUtil.removeUnderscores(article.apiTitle)\n                    ServiceFactory.get(currentWikiSite).searchMoreLike(\"morelike:$searchTerm\", 10, 10)\n                        .query?.pages?.filter { it.title != searchTerm && it.title != MainPageNameData.valueFor(languageCode) }?.map { page ->\n                            PageTitle(\n                                text = page.title,\n                                wiki = currentWikiSite,\n                                thumbUrl = page.thumbUrl(),\n                                description = page.description,\n                                displayText = page.displayTitle(languageCode),\n                            ).also {\n                                if (!page.sectionTitle.isNullOrEmpty()) it.fragment = StringUtil.addUnderscores(page.sectionTitle)\n                                it.extract = page.extract\n                            }\n                        }.orEmpty().map {\n                            // TODO: filter items that have already been suggested.\n                            BasedOnInterestCard(it, interestArticle = article)\n                        }.filterNot { hiddenCards.contains(it.hideKey) }.take(4)\n                }\n            }\n\n            // --- Because you read ---\n\n            val becauseYouReadDeferred = async(Dispatchers.IO) {\n                buildList {\n                    becauseYouReadSeed?.let { entry ->\n                        val hasParentLanguageCode = !WikipediaApp.instance.languageState.getDefaultLanguageCode(languageCode).isNullOrEmpty()\n                        val searchTerm = StringUtil.removeUnderscores(entry.title.prefixedText)\n\n                        var moreLikeMaxAge = 86400\n                        if (hasParentLanguageCode) {\n                            moreLikeMaxAge = 0\n                        }\n                        val moreLikeResponse = ServiceFactory.get(entry.title.wikiSite).searchMoreLike(\"morelike:$searchTerm\",\n                            Constants.SUGGESTION_REQUEST_ITEMS * 2, Constants.SUGGESTION_REQUEST_ITEMS * 2, sMaxAge = moreLikeMaxAge, maxAge = moreLikeMaxAge)\n\n                        val relatedPages = moreLikeResponse.query?.pages?.filter { it.title != searchTerm && it.title != MainPageNameData.valueFor(entry.title.wikiSite.languageCode) }?.map {\n                            PageSummary(\n                                it.displayTitle(languageCode),\n                                it.title,\n                                it.description,\n                                it.extract,\n                                it.thumbUrl(),\n                                languageCode\n                            )\n                        }?.take(Constants.SUGGESTION_REQUEST_ITEMS)\n\n                        addAll(relatedPages?.map {\n                            BecauseYouReadCard(\n                                it.getPageTitle(currentWikiSite),\n                                entry.title.displayText\n                            )\n                        } ?: emptyList())\n                    }\n                }.filterNot { hiddenCards.contains(it.hideKey) }.take(4)\n            }\n\n            // --- Continue reading ---\n\n            val continueReadingDeferred = async(Dispatchers.IO) {\n                val continueReadingCards = buildList {\n                    continueReadingSeed?.let { entry ->\n                        add(\n                            ContinueReadingCard(\n                                entry.title,\n                                HistoryEntry.SOURCE_HISTORY\n                            )\n                        )\n                    }\n                    AppDatabase.instance.readingListPageDao().getMostRecentSavedPagesByLang(languageCode, 10).take(2)\n                        .forEach {\n                            add(\n                                ContinueReadingCard(\n                                    ReadingListPage.toPageTitle(it),\n                                    HistoryEntry.SOURCE_READING_LIST\n                                )\n                            )\n                        }\n                }.filterNot { hiddenCards.contains(it.hideKey) }.take(4)\n                if (continueReadingCards.isNotEmpty()) {\n                    ServiceFactory.get(currentWikiSite).getInfoWithExtractsByPageTitles(continueReadingCards.map { it.title.prefixedText }.fastJoinToString(\"|\"))\n                        .query?.pages?.forEach { page ->\n                            continueReadingCards.find { it.title.prefixedText == StringUtil.addUnderscores(page.title) }?.let {\n                                it.title.description = page.description\n                                it.title.thumbUrl = page.thumbUrl()\n                                it.title.displayText = page.displayTitle(languageCode)\n                                it.title.extract = page.extract\n                            }\n                        }\n                }\n                continueReadingCards\n            }\n\n            // --- Random article ---\n\n            val randomDeferred = async(Dispatchers.IO) {\n                val random = ServiceFactory.getRest(currentWikiSite).getRandomSummary()\n                RandomCard(random.getPageTitle(currentWikiSite))\n            }\n\n            // -- Read aloud lead section --\n\n            val readAloudLeadSectionTest = ReadAloudLeadSectionABTest()\n            if (readAloudLeadSectionTest.isTestActive() &&\n                ReadAloudArticlesRepository.isSupported(currentWikiSite) &&\n                AppDatabase.instance.topicInterestDao().hasAnyTopics()) {\n                readAloudLeadSectionTest.maybeSendExposureEvent()\n            }\n\n            val readAloudDeferred = async(Dispatchers.IO) {\n                if (!readAloudLeadSectionTest.isTestActive() ||\n                    !readAloudLeadSectionTest.isTestGroupUser() ||\n                    !ReadAloudArticlesRepository.isSupported(currentWikiSite)) {\n                    return@async emptyList()\n                }\n                // All the cards in this module come from a single topic, so the first of the user's\n                // topics that has any articles with an audio version supplies the whole module.\n                val readAloudCards = mutableListOf<ReadAloudLeadSectionCard>()\n                AppDatabase.instance.topicInterestDao().getAllRandom().firstOrNull()?.let { topic ->\n                    val readAloudTitles = ReadAloudArticlesRepository\n                        .randomArticlesForTopic(currentWikiSite, topic.topicId, 4)\n                    if (readAloudTitles.isNotEmpty()) {\n                        readAloudCards.addAll(ServiceFactory.get(currentWikiSite)\n                            .getInfoWithExtractsByPageTitles(readAloudTitles.fastJoinToString(\"|\") { it.prefixedText })\n                            .query?.pages?.map { page ->\n                                PageSummary(\n                                    prefixTitle = page.title,\n                                    displayTitle = page.displayTitle(currentWikiSite.languageCode),\n                                    description = page.description,\n                                    extract = page.extract,\n                                    thumbnail = page.thumbUrl(),\n                                    lang = currentWikiSite.languageCode,\n                                    pageId = page.pageId,\n                                    revision = page.lastrevid\n                                )\n                            }?.map { summary ->\n                                ReadAloudLeadSectionCard(summary, topic)\n                            }?.filterNot { hiddenCards.contains(it.hideKey) }.orEmpty())\n                    }\n                }\n                readAloudCards\n            }\n\n            // Combine all the deferred results and add them to the modules list if they have content.\n\n            readAloudDeferred.await().let {\n                if (it.isNotEmpty()) {\n                    // The index for this module is always 0 because there is always a single instance of this module, per age.\n                    modules.add(ForYouModule.ReadAloudLeadSection(age, 0, it))\n                }\n            }\n            interestTopicCalls.awaitAll().forEachIndexed { index, entries ->\n                if (entries.isNotEmpty()) {\n                    modules.add(ForYouModule.BasedOnInterest(age, index, entries))\n                }\n            }\n            interestArticleCalls.awaitAll().forEachIndexed { index, entries ->\n                if (entries.isNotEmpty()) {\n                    modules.add(ForYouModule.BasedOnInterest(age, index, entries))\n                }\n            }\n            becauseYouReadDeferred.await().let {\n                if (it.isNotEmpty()) {\n                    // The index for this module is always 0 because there is always a single instance of this module, per age.\n                    modules.add(ForYouModule.BecauseYouRead(age, 0, it))\n                }\n            }\n            continueReadingDeferred.await().let {\n                if (it.isNotEmpty()) {\n                    // The index for this module is always 0 because there is always a single instance of this module, per age.\n                    modules.add(ForYouModule.ContinueReading(age, 0, it))\n                }\n            }\n            randomDeferred.await().let { randomCard ->\n                if (!hiddenCards.contains(randomCard.hideKey)) {\n                    // The index for this module is always 0 because there is always a single instance of this module, per age.\n                    modules.add(ForYouModule.Random(age, 0, listOf(randomCard)))\n                }\n            }\n        }\n\n        _forYouNetworkLatency.value = System.currentTimeMillis() - startMillis\n\n        forYouCollectionSaved = ForYouCollectionSaved(\n            dateTime = currentDateTime,\n            modulesPerLanguage = cachedModulesByLanguage + (languageCode to modules)\n        )\n        withContext(Dispatchers.Default) {\n            Prefs.homeForYouModulesToday = JsonUtil.encodeToString(forYouCollectionSaved).orEmpty()\n        }\n        return modules\n    }\n\n    private suspend fun getRandomSeedEntries(langCode: String, limit: Int): List<HistoryEntry> {\n        val sinceMillis = LocalDate.now().minusDays(RECENT_ARTICLES_SEED_WINDOW_DAYS)\n            .atStartOfDay(ZoneId.systemDefault()).toInstant().toEpochMilli()\n        return AppDatabase.instance.historyEntryWithImageDao().findRandomSeedEntriesForReadMore(\n            limit = limit,\n            minTimeSpent = RECENT_ARTICLES_MIN_TIME_SPENT_SEC,\n            sinceMillis = sinceMillis,\n            langCode = langCode\n        )\n    }\n\n    private suspend fun buildDiscoverModule(): ForYouModule.Discover? {\n        if (!Prefs.isRecommendedReadingListEnabled) {\n            return ForYouModule.Discover(age = 0, index = 0, cards = emptyList(), isEnabled = false)\n        }\n        val pages = RecommendedReadingListHelper.generateRecommendedReadingList(Prefs.resetRecommendedReadingList)\n\n        val displayPages = pages.take(MAX_DISCOVER_ARTICLE_CARDS)\n        if (displayPages.isEmpty()) {\n            return null\n        }\n        updateMissingExtracts(displayPages)\n        val cards = displayPages.map { page ->\n            DiscoverCard(\n                PageTitle(\n                    text = page.apiTitle,\n                    wiki = page.wiki,\n                    thumbUrl = page.thumbUrl,\n                    description = page.description,\n                    displayText = page.displayTitle,\n                    extract = page.extract\n                )\n            )\n        }\n        val displayCards = if (pages.size > MAX_DISCOVER_ARTICLE_CARDS) cards + SeeAllRecommendationCard() else cards\n        return ForYouModule.Discover(\n            age = 0,\n            index = 0,\n            cards = displayCards,\n            isEnabled = true,\n            updateFrequency = Prefs.recommendedReadingListUpdateFrequency\n        )\n    }\n\n    /**\n     * Pages cached before the [RecommendedPage.extract] column existed have a null extract.\n     * This function fetches those null extracts in a single batched request and saves them to DB.\n     */\n    private suspend fun updateMissingExtracts(pages: List<RecommendedPage>) {\n        val missing = pages.filter { it.extract == null }\n        if (missing.isEmpty()) {\n            return\n        }\n        runCatching {\n            ServiceFactory.get(wikiSite.value)\n                .getInfoWithExtractsByPageTitles(missing.fastJoinToString(\"|\") { it.apiTitle })\n                .query?.pages?.forEach { page ->\n                    missing.find { it.apiTitle == StringUtil.addUnderscores(page.title) }?.extract = page.extract\n                }\n        }.onFailure { L.e(it) }\n        AppDatabase.instance.recommendedPageDao().updateAll(missing.filter { it.extract != null })\n    }\n\n    private suspend fun buildPlacesModule(): ForYouModule.PlacesOfInterest? {\n        if (!hasLocationPermission()) {\n            return ForYouModule.PlacesOfInterest(age = 0, index = 0, cards = emptyList(), hasLocationPermission = false)\n        }\n        val location = Prefs.placesLastLocationAndZoomLevel?.first\n            ?: return ForYouModule.PlacesOfInterest(age = 0, index = 0, cards = emptyList(), hasLocationPermission = false)\n\n        val cards = getPlacesCards(location)\n        if (cards.isEmpty()) {\n            return null\n        }\n        return ForYouModule.PlacesOfInterest(age = 0, index = 0, cards = cards, hasLocationPermission = true)\n    }\n\n    private suspend fun buildGameModule(supportedGames: List<WikiGames>): ForYouModule.Games {\n        val today = LocalDate.now()\n        val gameCards = supportedGames\n            .mapNotNull { buildWikiGame(it, today)?.let { game ->\n                WikiGameCard(\n                    game,\n                    today.toString()\n                )\n            } }\n        val cards = gameCards + GamesModulePromptCard()\n\n        return ForYouModule.Games(age = 0, index = 0, cards = cards)\n    }\n\n    private suspend fun buildWikiGame(game: WikiGames, date: LocalDate): WikiGame? = when (game) {\n        WikiGames.WHICH_CAME_FIRST -> {\n            val state = OnThisDayGameProvider.getGameState(wikiSite.value, date)\n            WikiGame.OnThisDayGame(state)\n        }\n    }\n\n    private suspend fun getPlacesCards(savedLocation: Location): List<PlacesOfInterestCard> {\n        val coordinates = \"${savedLocation.latitude}|${savedLocation.longitude}\"\n        return ServiceFactory.get(wikiSite.value)\n            .getGeoSearchWithExtracts(coordinates, PLACES_SEARCH_RADIUS_METERS, PLACES_ARTICLES_REQUEST_LIMIT, PLACES_ARTICLES_REQUEST_LIMIT)\n            .query?.pages.orEmpty()\n            .filter { it.coordinates != null }\n            .sortedBy {\n                savedLocation.distanceTo(Location(\"\").apply {\n                    latitude = it.coordinates!![0].lat\n                    longitude = it.coordinates[0].lon\n                })\n            }\n            .map { page ->\n                val title = PageTitle(\n                    text = page.title,\n                    wiki = wikiSite.value,\n                    thumbUrl = page.thumbUrl(),\n                    description = page.description,\n                    displayText = page.displayTitle(wikiSite.value.languageCode),\n                    extract = page.extract\n                )\n                val articleLocation = Location(\"\").apply {\n                    latitude = page.coordinates!![0].lat\n                    longitude = page.coordinates[0].lon\n                }\n                val distance = GeoUtil.getDistanceWithUnit(savedLocation, articleLocation, Locale.getDefault())\n                PlacesOfInterestCard(title, distance)\n            }\n    }\n\n    private fun getSupportedGames(languageCode: String): List<WikiGames> {\n        return WikiGames.entries.filter { it.isLangSupported(languageCode) }\n    }\n\n    private fun hasLocationPermission(): Boolean {\n        val context = WikipediaApp.instance\n        return ContextCompat.checkSelfPermission(context, Manifest.permission.ACCESS_FINE_LOCATION) == PackageManager.PERMISSION_GRANTED ||\n                ContextCompat.checkSelfPermission(context, Manifest.permission.ACCESS_COARSE_LOCATION) == PackageManager.PERMISSION_GRANTED\n    }\n\n    fun refreshUnreadNotificationCount() {\n        _unreadCount.update { it.copy(unreadCount = Prefs.notificationUnreadCount, canShow = AccountUtil.isLoggedIn) }\n    }\n}","file":"app/src/main/java/org/wikipedia/feed/HomeViewModel.kt","kind":"class","line":232,"members":{"_communityState":[241,241],"_forYouNetworkLatency":[443,443],"_forYouState":[362,362],"_savedInReadingApiTitles":[400,402],"_selectedTab":[236,238],"_tabsState":[397,397],"_unreadCount":[440,440],"_wikiSite":[233,233],"buildDiscoverModule":[898,929],"buildGameModule":[964,976],"buildPlacesModule":[950,962],"buildWikiGame":[978,983],"communityHandler":[424,430],"communityState":[242,258],"discoverModule":[286,319],"ensureContentLoaded":[475,492],"fetchForYouModules":[637,885],"forYouBatchIndex":[394,395],"forYouHandler":[432,438],"forYouNetworkLatency":[444,444],"forYouState":[363,389],"gameModule":[321,355],"getPlacesCards":[985,1013],"getRandomSeedEntries":[887,896],"getSupportedGames":[1015,1017],"hasLocationPermission":[1019,1023],"hideCommunityCard":[601,605],"hideForYouCard":[613,617],"hideModule":[625,629],"loadCommunityContent":[509,569],"loadForYouContent":[571,599],"nextCommunityAge":[391,392],"placesModule":[260,284],"reactiveModules":[357,360],"refreshCommunityContent":[459,463],"refreshForYouContent":[465,469],"refreshUnreadNotificationCount":[1025,1027],"restoreCommunityCard":[607,611],"restoreForYouCard":[619,623],"restoreModule":[631,635],"savedInReadingListTitles":[404,422],"selectTab":[471,473],"selectedTab":[239,239],"tabsState":[398,398],"unreadCount":[441,441],"updateLanguage":[494,497],"updateMissingExtracts":[931,948],"updateSelectedLanguageIfNeeded":[503,507],"updateTabCount":[499,501],"wikiSite":[234,234]},"supers":["ViewModel()"]},"LanguageDropDownMenu":{"appearsIn":[["home","h-widgets","Screen \u00b7 composition"]],"code":"@Composable\nfun LanguageDropDownMenu(\n    selectedLanguageCode: String,\n    onLanguageSelected: (String) -> Unit,\n    onManageLanguagesClick: () -> Unit,\n    languageState: AppLanguageState? = null\n) {\n    var expanded by remember { mutableStateOf(false) }\n    Box(\n        modifier = Modifier\n            .padding(horizontal = 8.dp)\n            .clip(RoundedCornerShape(8.dp))\n            .clickable {\n                expanded = true\n            },\n        contentAlignment = Alignment.Center\n    ) {\n        Row(\n            modifier = Modifier\n                .border(\n                    width = 1.dp,\n                    color = WikipediaTheme.colors.primaryColor.copy(alpha = 0.8f),\n                    shape = RoundedCornerShape(8.dp)\n                )\n                .padding(4.dp),\n            horizontalArrangement = Arrangement.Center,\n            verticalAlignment = Alignment.CenterVertically\n        ) {\n            WikiLangCodeBox(\n                modifier = Modifier\n                    .height(20.dp)\n                    .widthIn(min = 20.dp),\n                languageCode = selectedLanguageCode,\n                backgroundColor = WikipediaTheme.colors.primaryColor.copy(alpha = 0.8f),\n                borderColor = Color.Transparent,\n                textColor = WikipediaTheme.colors.paperColor,\n            )\n            Icon(\n                modifier = Modifier.size(16.dp),\n                painter = painterResource(R.drawable.ic_arrow_down_24),\n                contentDescription = null,\n                tint = WikipediaTheme.colors.primaryColor\n            )\n        }\n        DropdownMenu(\n            expanded = expanded,\n            containerColor = WikipediaTheme.colors.paperColor,\n            onDismissRequest = { expanded = false }\n        ) {\n            val languageCodes = languageState?.appLanguageCodes.orEmpty()\n            repeat(languageCodes.size) {\n                val langCode = languageCodes[it]\n                DropdownMenuItem(\n                    leadingIcon = {\n                        WikiLangCodeBox(\n                            modifier = Modifier\n                                .height(20.dp)\n                                .widthIn(min = 20.dp),\n                            languageCode = langCode,\n                            borderColor = WikipediaTheme.colors.secondaryColor,\n                            textColor = WikipediaTheme.colors.secondaryColor,\n                        )\n                    },\n                    trailingIcon = {\n                        if (langCode == selectedLanguageCode) {\n                            Icon(\n                                painter = painterResource(R.drawable.ic_check_black_24dp),\n                                contentDescription = null,\n                                tint = WikipediaTheme.colors.secondaryColor\n                            )\n                        }\n                    },\n                    text = {\n                        Text(\n                            text = languageState?.getAppLanguageLocalizedName(langCode) ?: langCode,\n                            style = MaterialTheme.typography.bodyLarge,\n                            color = WikipediaTheme.colors.primaryColor\n                        )\n                    },\n                    onClick = {\n                        onLanguageSelected(langCode)\n                        expanded = false\n                    }\n                )\n            }\n\n            HorizontalDivider(\n                modifier = Modifier.padding(vertical = 8.dp),\n                color = WikipediaTheme.colors.borderColor\n            )\n\n            Column(\n                modifier = Modifier\n                    .fillMaxWidth()\n                    .clickable {\n                        onManageLanguagesClick()\n                        expanded = false\n                    }\n                    .padding(vertical = 8.dp),\n            ) {\n                Text(\n                    modifier = Modifier.padding(horizontal = 16.dp),\n                    text = LocalContext.current.getString(selectedLanguageCode, R.string.explore_feed_manage_languages_label),\n                    style = MaterialTheme.typography.bodyLarge,\n                    color = WikipediaTheme.colors.primaryColor\n                )\n            }\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/feed/HomeScreen.kt","kind":"composable function","line":335,"members":{},"shot":"shots/code/LanguageDropDownMenu.jpg","supers":[]},"LoadMoreButton":{"appearsIn":[["home","h-widgets","Screen \u00b7 composition"]],"code":"@Composable\nfun LoadMoreButton(\n    wikiSite: WikiSite,\n    isCommunity: Boolean = true,\n    onClick: () -> Unit\n) {\n    Box(\n        modifier = Modifier.fillMaxWidth(),\n        contentAlignment = Alignment.Center\n    ) {\n        if (isCommunity) {\n            AppButton(\n                modifier = Modifier.padding(horizontal = 24.dp, vertical = 16.dp),\n                onClick = onClick,\n            ) {\n                Row(\n                    verticalAlignment = Alignment.CenterVertically\n                ) {\n                    Icon(\n                        painter = painterResource(R.drawable.ic_dynamic_feed_24dp),\n                        tint = WikipediaTheme.colors.paperColor,\n                        contentDescription = null\n                    )\n\n                    Spacer(modifier = Modifier.width(16.dp))\n\n                    Text(\n                        text = LocalContext.current.getString(wikiSite.languageCode, R.string.explore_feed_community_load_more_label),\n                        style = MaterialTheme.typography.titleMedium,\n                        fontWeight = FontWeight.Medium,\n                        color = WikipediaTheme.colors.paperColor\n                    )\n                }\n            }\n        } else {\n            Box(\n                modifier = Modifier\n                    .padding(16.dp),\n                contentAlignment = Alignment.Center\n            ) {\n                TextButton(onClick = onClick) {\n                    Text(\n                        text = \"Load more recommendations\",\n                        color = WikipediaTheme.colors.progressiveColor,\n                        fontWeight = FontWeight.Medium\n                    )\n                }\n            }\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/feed/FeedComponents.kt","kind":"composable function","line":94,"members":{},"supers":[]},"NewsCard":{"appearsIn":[["home","h-classes","Logic \u00b7 class diagram"]],"code":"class NewsCard(\n    val news: List<NewsItem>,\n    val age: Int,\n    wiki: WikiSite\n) : WikiSiteCard(wiki) {\n\n    override fun moduleKey(): String {\n        return CommunityModuleType.NEWS.name\n    }\n\n    override fun dismissHashCode(): Int {\n        return TimeUnit.MILLISECONDS.toDays(date().baseCalendar.time.time).toInt() + wikiSite().hashCode() + moduleKey().hashCode()\n    }\n\n    fun date(): UtcDate {\n        return UtcDate(age)\n    }\n}","file":"app/src/main/java/org/wikipedia/feed/model/NewsCard.kt","kind":"class","line":8,"members":{"age":[10,10],"date":[22,24],"dismissHashCode":[18,20],"moduleKey":[14,16],"news":[9,9],"wiki":[11,11]},"supers":["WikiSiteCard(wiki)"]},"OnThisDayCard":{"appearsIn":[["home","h-classes","Logic \u00b7 class diagram"]],"code":"class OnThisDayCard(val events: List<OnThisDay.Event>, val age: Int, wiki: WikiSite) : WikiSiteCard(wiki) {\n    private val date: Calendar = DateUtil.getDefaultDateFor(age)\n\n    override fun moduleKey(): String {\n        return CommunityModuleType.ON_THIS_DAY.name\n    }\n\n    override fun dismissHashCode(): Int {\n        return TimeUnit.MILLISECONDS.toDays(date.time.time).toInt() + wikiSite().hashCode() + moduleKey().hashCode()\n    }\n}","file":"app/src/main/java/org/wikipedia/feed/model/OnThisDayCard.kt","kind":"class","line":10,"members":{"age":[10,10],"date":[11,11],"dismissHashCode":[17,19],"events":[10,10],"moduleKey":[13,15],"wiki":[10,10]},"supers":["WikiSiteCard(wiki)"]},"ServiceFactory":{"appearsIn":[["activity","h-classes","Logic \u00b7 class diagram"],["activity","h-sequence","Open the Activity tab, logged in \u00b7 sequence"],["home","h-classes","Logic \u00b7 class diagram"],["home","h-sequence","Load more of the Community feed \u00b7 sequence"],["index","h-services","Services \u00b7 what the screens share"],["places","h-classes","Logic \u00b7 class diagram"],["places","h-sequence","Pan the map and open a place \u00b7 sequence"],["search","h-classes","Logic \u00b7 class diagram"],["search","h-sequence","Type a query \u00b7 sequence"]],"code":"object ServiceFactory {\n\n    private const val SERVICE_CACHE_SIZE = 8\n\n    private val SERVICE_CACHE = lruCache<WikiSite, Service>(SERVICE_CACHE_SIZE, create = {\n        // This method is called in the get() method if a value does not already exist.\n        createRetrofit(it, getBasePath(it)).create<Service>()\n    })\n\n    private val REST_SERVICE_CACHE = lruCache<WikiSite, RestService>(SERVICE_CACHE_SIZE, create = {\n        createRetrofit(it, getRestBasePath(it)).create<RestService>()\n    })\n\n    private val CORE_REST_SERVICE_CACHE = lruCache<WikiSite, CoreRestService>(SERVICE_CACHE_SIZE, create = {\n        createRetrofit(it, it.url() + \"/\" + CoreRestService.CORE_REST_API_PREFIX).create<CoreRestService>()\n    })\n\n    private val ANALYTICS_REST_SERVICE_CACHE = lruCache<DestinationEventService, EventService>(SERVICE_CACHE_SIZE, create = {\n        val intakeBaseUriOverride = Prefs.eventPlatformIntakeUriOverride.orEmpty().ifEmpty { it.baseUri }\n        createRetrofit(null, intakeBaseUriOverride).create<EventService>()\n    })\n\n    fun get(wiki: WikiSite): Service {\n        return SERVICE_CACHE[wiki]!!\n    }\n\n    fun getRest(wiki: WikiSite): RestService {\n        return REST_SERVICE_CACHE[wiki]!!\n    }\n\n    fun getCoreRest(wiki: WikiSite): CoreRestService {\n        return CORE_REST_SERVICE_CACHE[wiki]!!\n    }\n\n    fun getAnalyticsRest(destinationEventService: DestinationEventService): EventService {\n        return ANALYTICS_REST_SERVICE_CACHE[destinationEventService]!!\n    }\n\n    operator fun <T> get(wiki: WikiSite, baseUrl: String?, service: Class<T>): T {\n        val r = createRetrofit(wiki, baseUrl.orEmpty().ifEmpty { wiki.url() + \"/\" })\n        return r.create(service)\n    }\n\n    fun getBasePath(wiki: WikiSite): String {\n        var path = wiki.url()\n        if (!path.endsWith(\"/\")) {\n            path += \"/\"\n        }\n        return path\n    }\n\n    fun getRestBasePath(wiki: WikiSite): String {\n        var path = if (Prefs.restbaseUriFormat.isEmpty()) wiki.url() + \"/\" + RestService.REST_API_PREFIX\n        else String.format(Prefs.restbaseUriFormat, \"https\", wiki.authority())\n        if (!path.endsWith(\"/\")) {\n            path += \"/\"\n        }\n        return path\n    }\n\n    fun createRetrofit(wiki: WikiSite?, baseUrl: String, readTimeoutSec: Long = OkHttpConnectionFactory.DEFAULT_READ_TIMEOUT_SEC): Retrofit {\n        val builder = OkHttpConnectionFactory.client.newBuilder()\n        builder.readTimeout(readTimeoutSec, TimeUnit.SECONDS)\n        builder.interceptors().add(builder.interceptors().indexOfFirst { it is HttpLoggingInterceptor }, LanguageVariantHeaderInterceptor(wiki))\n\n        return Retrofit.Builder()\n            .baseUrl(baseUrl)\n            .client(builder.build())\n            .addConverterFactory(MwExceptionConverterFactory())\n            .build()\n    }\n\n    private class LanguageVariantHeaderInterceptor(private val wiki: WikiSite?) : Interceptor {\n        @Throws(IOException::class)\n        override fun intercept(chain: Interceptor.Chain): Response {\n            var request = chain.request().newBuilder()\n                .header(\"Accept-Language\", WikipediaApp.instance.getAcceptLanguage(wiki))\n                .build()\n            return chain.proceed(request)\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/dataclient/ServiceFactory.kt","kind":"object","line":18,"members":{"ANALYTICS_REST_SERVICE_CACHE":[35,38],"CORE_REST_SERVICE_CACHE":[31,33],"LanguageVariantHeaderInterceptor":[90,98],"REST_SERVICE_CACHE":[27,29],"SERVICE_CACHE":[22,25],"SERVICE_CACHE_SIZE":[20,20],"createRetrofit":[78,88],"get":[40,42],"getAnalyticsRest":[52,54],"getBasePath":[61,67],"getCoreRest":[48,50],"getRest":[44,46],"getRestBasePath":[69,76]},"supers":[]},"TopReadCard":{"appearsIn":[["home","h-classes","Logic \u00b7 class diagram"]],"code":"@Parcelize\nclass TopReadCard(\n    val articles: TopRead,\n    val age: Int,\n    val site: WikiSite\n) : Card(), Parcelable {\n\n    override fun moduleKey(): String {\n        return CommunityModuleType.TOP_READ.name\n    }\n\n    override fun dismissHashCode(): Int {\n        return articles.localDate.toEpochDay().toInt() + site.hashCode() + moduleKey().hashCode()\n    }\n}","file":"app/src/main/java/org/wikipedia/feed/model/TopReadCard.kt","kind":"class","line":9,"members":{"age":[12,12],"articles":[11,11],"dismissHashCode":[20,22],"moduleKey":[16,18],"site":[13,13]},"supers":["Card()","Parcelable"]}},"sourceUrl":"https://github.com/wikimedia/apps-android-wikipedia/blob/a94b2dd658c6a6bdc7f131c5bf5fa97ba9ae6bfd/"};
